#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BoundedLineRead {
    Eof,
    Line,
    TooLong,
}

fn read_bounded_line<R: BufRead>(
    reader: &mut R,
    output: &mut String,
    max_bytes: usize,
) -> io::Result<BoundedLineRead> {
    output.clear();
    let mut bytes = Vec::with_capacity(8192.min(max_bytes.saturating_add(1)));
    let read = {
        let mut limited = reader.take(max_bytes.saturating_add(1) as u64);
        limited.read_until(b'\n', &mut bytes)?
    };
    if read == 0 {
        return Ok(BoundedLineRead::Eof);
    }

    let has_newline = bytes.last() == Some(&b'\n');
    let content_len = bytes.len().saturating_sub(usize::from(has_newline));
    if content_len > max_bytes {
        loop {
            let available = reader.fill_buf()?;
            if available.is_empty() {
                break;
            }
            let newline = available.iter().position(|byte| *byte == b'\n');
            let consumed = newline.map_or(available.len(), |index| index + 1);
            reader.consume(consumed);
            if newline.is_some() {
                break;
            }
        }
        return Ok(BoundedLineRead::TooLong);
    }

    *output = String::from_utf8(bytes)
        .map_err(|error| io::Error::new(io::ErrorKind::InvalidData, error))?;
    Ok(BoundedLineRead::Line)
}

fn normalize_loopback_bridge_host(host: &str) -> Result<String> {
    let raw = host.trim();
    let normalized = if raw.is_empty() || raw.eq_ignore_ascii_case("localhost") {
        "127.0.0.1".to_string()
    } else {
        raw.strip_prefix('[')
            .and_then(|value| value.strip_suffix(']'))
            .unwrap_or(raw)
            .to_string()
    };
    let address: IpAddr = normalized
        .parse()
        .with_context(|| format!("Bridge host must be a loopback IP address, got {raw:?}"))?;
    if !address.is_loopback() {
        bail!(
            "Renium only permits loopback bridge hosts (127.0.0.1 or ::1); refusing {raw:?} because the bridge has no remote authentication"
        );
    }
    Ok(address.to_string())
}

fn loopback_host_port(host: &str, port: u16) -> String {
    if host.contains(':') {
        format!("[{host}]:{port}")
    } else {
        format!("{host}:{port}")
    }
}

fn is_loopback_endpoint(address: &std::net::SocketAddr) -> bool {
    address.ip().is_loopback()
}

fn bridge_response_timeout(method: &str) -> Duration {
    match method {
        "prepare"
        | "applyEditorChanges"
        | "beginEditorTransaction"
        | "commitEditorTransaction"
        | "rollbackEditorTransaction"
        | "appendEditorBinaryImport"
        | "appendEditorPushReview"
        | "finishEditorBinaryImport"
        | "awaitEditorBinaryExport"
        | "profilePluginOps"
        | "getInstanceBatchChunk"
        | "getInstanceBatchCompactChunk"
        | "getEditorBinaryOverlayChunk"
        | "getEditorBinaryDebugIds"
        | "getSourceBatchChunk"
        | "getSourceRangeBatchCompactChunk" => BRIDGE_SLOW_RESPONSE_TIMEOUT,
        _ => BRIDGE_DEFAULT_RESPONSE_TIMEOUT,
    }
}

fn bridge_channel_lock_timeout(method: &str) -> Duration {
    match method {
        "appendEditorBinaryImport" | "appendEditorPushReview" => BRIDGE_SLOW_RESPONSE_TIMEOUT,
        _ => BRIDGE_CHANNEL_LOCK_TIMEOUT,
    }
}

fn clamp_bridge_chunk_size(size: usize) -> usize {
    size.clamp(MIN_BRIDGE_CHUNK_BYTES, MAX_BRIDGE_CHUNK_BYTES)
}
