fn elapsed_ms(started: Instant) -> f64 {
    started.elapsed().as_secs_f64() * 1000.0
}

fn log_timing(label: &str, started: Instant) {
    if QUIET_TIMINGS.load(Ordering::Relaxed) || !global_log_enabled(3) {
        return;
    }
    println!("[renium] timing: {label} took {:.1}ms", elapsed_ms(started));
}

fn log_timing_ms(label: &str, elapsed_ms: f64) {
    if !global_log_enabled(3) {
        return;
    }
    if QUIET_TIMINGS.load(Ordering::Relaxed)
        && !matches!(
            label,
            "cli start to bridge listen"
                | "bridge listen to all channels connected"
                | "bridge bind/listen setup"
                | "all channels connected to bridge info"
                | "bridge info to property schema ready"
                | "property schema ready to first service export"
                | "first service export to last service export"
                | "last service export to dispatcher drain start"
                | "direct import dispatcher drain"
                | "write generated project"
                | "sourcemap finalize"
                | "full export-snapshots run"
        )
    {
        return;
    }
    println!("[renium] timing: {label} took {elapsed_ms:.1}ms");
}

fn verbose_timing_logs() -> bool {
    !QUIET_TIMINGS.load(Ordering::Relaxed) && global_log_enabled(3)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PerformanceMode {
    Throughput,
    Balanced,
    Smooth,
}

impl PerformanceMode {
    fn parse(raw: &str) -> Self {
        match raw {
            "smooth" => Self::Smooth,
            "balanced" => Self::Balanced,
            _ => Self::Throughput,
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Throughput => "throughput",
            Self::Balanced => "balanced",
            Self::Smooth => "smooth",
        }
    }

    fn min_large_service_batch_size(
        self,
        instance_count: usize,
        bridge_concurrency: usize,
    ) -> usize {
        match self {
            Self::Throughput => {
                if instance_count < 20_000 {
                    return instance_count.max(1);
                }
                let target_ranges = bridge_concurrency.max(1).min(instance_count.max(1));
                instance_count.div_ceil(target_ranges).max(1)
            }
            Self::Balanced => {
                if instance_count < LARGE_SERVICE_SINGLE_WAVE_MIN_INSTANCES {
                    return 0;
                }
                instance_count.div_ceil(8).max(1)
            }
            Self::Smooth => 0,
        }
    }

    fn large_service_worker_floor(self, instance_count: usize, bridge_concurrency: usize) -> usize {
        if instance_count < LARGE_SERVICE_SINGLE_WAVE_MIN_INSTANCES {
            return 0;
        }
        match self {
            Self::Throughput | Self::Balanced => bridge_concurrency.max(1),
            Self::Smooth => 0,
        }
    }

    fn cached_tune_max_frame_cap_ms(self) -> f64 {
        match self {
            Self::Throughput => 100.0,
            Self::Balanced => 50.0,
            Self::Smooth => 33.0,
        }
    }

    fn cached_tune_stall_cap(self) -> u64 {
        match self {
            Self::Throughput => 1,
            Self::Balanced | Self::Smooth => 0,
        }
    }
}

