fn automation_bridge_args(parameters: &Value, positional: &[&str]) -> Result<Vec<String>> {
    let object = parameters.as_object().context("p must be an object")?;
    if object.contains_key("a") {
        return automation_payload_args(parameters);
    }
    let mut arguments = positional
        .iter()
        .filter_map(|key| automation_string(object, key))
        .collect::<Vec<_>>();
    let mut flags = object.clone();
    for key in positional {
        flags.remove(*key);
    }
    arguments.extend(automation_payload_args(&Value::Object(flags))?);
    Ok(arguments)
}

fn automation_place_alias(value: &str, place_id: i64) -> String {
    let mut output = String::new();
    let mut separator = false;
    for character in value.to_ascii_lowercase().chars() {
        if character.is_ascii_alphanumeric() {
            if separator && !output.is_empty() {
                output.push('_');
            }
            output.push(character);
            separator = false;
        } else if character.is_ascii_whitespace() || character == '_' {
            separator = !output.is_empty();
        }
    }
    if output.is_empty() {
        format!("place{place_id}")
    } else {
        output
    }
}

fn automation_write_experience(path: &Path, manifest: &Value) -> Result<()> {
    let temporary = path.with_file_name(format!(
        ".renium.experience.{}.{}.tmp",
        std::process::id(),
        current_millis()
    ));
    fs::write(&temporary, serde_json::to_vec_pretty(manifest)?)
        .with_context(|| format!("Failed to write {}", temporary.display()))?;
    replace_file_with_backup(&temporary, path, "experience manifest")
}

fn automation_read_experience(context: &automation::BoundContext) -> Result<(PathBuf, Value)> {
    let path = Path::new(&context.experience).join("renium.experience.json");
    let manifest = serde_json::from_slice(
        &fs::read(&path).with_context(|| format!("Failed to read {}", path.display()))?,
    )?;
    Ok((path, manifest))
}

fn automation_place_add(context: &automation::BoundContext, parameters: &Value) -> Result<Value> {
    let object = parameters.as_object().context("p must be an object")?;
    let place_id = object
        .get("placeId")
        .and_then(Value::as_i64)
        .context("place-add requires p.placeId")?;
    let game_id = object
        .get("gameId")
        .and_then(Value::as_i64)
        .or(context.game_id)
        .unwrap_or(0);
    let name = automation_string(object, "name").context("place-add requires p.name")?;
    let requested_alias = automation_string(object, "alias").unwrap_or_else(|| name.clone());
    let alias = automation_place_alias(&requested_alias, place_id);
    let experience = Path::new(&context.experience);
    let manifest_path = experience.join("renium.experience.json");
    let mut manifest = if manifest_path.is_file() {
        serde_json::from_slice::<Value>(&fs::read(&manifest_path)?)?
    } else {
        let current_name = Path::new(&context.root)
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or("main")
            .to_string();
        let current_alias = automation_place_alias(&current_name, context.place_id.unwrap_or(0));
        let current_root = experience.join("places").join(&current_alias);
        fs::create_dir_all(&current_root)?;
        for entry in [
            PathBuf::from("renium.project.jsonc"),
            PathBuf::from("renium.project.json"),
            PathBuf::from(&context.source)
                .strip_prefix(&context.root)
                .unwrap_or(Path::new("src"))
                .to_path_buf(),
            PathBuf::from(".renium"),
            PathBuf::from("sourcemap.json"),
            PathBuf::from("renium-link.json"),
            PathBuf::from("wally.toml"),
            PathBuf::from("wally.lock"),
            PathBuf::from("Packages"),
        ] {
            let source = experience.join(&entry);
            let destination = current_root.join(&entry);
            if source.exists() {
                if destination.exists() {
                    bail!(
                        "Cannot migrate {} because {} already exists",
                        source.display(),
                        destination.display()
                    );
                }
                if let Some(parent) = destination.parent() {
                    fs::create_dir_all(parent)?;
                }
                fs::rename(&source, &destination)
                    .with_context(|| format!("Failed to move {}", source.display()))?;
            }
        }
        json!({
            "version": 2,
            "gameId": context.game_id.unwrap_or(game_id),
            "startPlace": current_alias.clone(),
            "placeOrder": context.place_id.filter(|id| *id > 0).into_iter().collect::<Vec<_>>(),
            "places": {
                (current_alias.clone()): {
                    "placeId": context.place_id.unwrap_or(0),
                    "name": current_name,
                    "root": format!("places/{current_alias}")
                }
            }
        })
    };
    let manifest_game_id = manifest.get("gameId").and_then(Value::as_i64).unwrap_or(0);
    if manifest_game_id > 0 && game_id > 0 && manifest_game_id != game_id {
        bail!("Place gameId {game_id} does not match project gameId {manifest_game_id}");
    }
    let places = manifest
        .get_mut("places")
        .and_then(Value::as_object_mut)
        .context("Experience places must be an object")?;
    if places.contains_key(&alias)
        || places
            .values()
            .any(|place| place.get("placeId").and_then(Value::as_i64) == Some(place_id))
    {
        bail!("Place {place_id} is already configured");
    }
    let relative_root =
        automation_string(object, "root").unwrap_or_else(|| format!("places/{alias}"));
    let relative_path = Path::new(&relative_root);
    if relative_path.is_absolute()
        || relative_path.components().any(|component| {
            matches!(
                component,
                std::path::Component::ParentDir
                    | std::path::Component::RootDir
                    | std::path::Component::Prefix(_)
            )
        })
    {
        bail!("Place root must be a relative path inside the experience project");
    }
    let place_root = experience.join(&relative_root);
    if !place_root.starts_with(experience) || place_root == experience {
        bail!("Place root must stay inside the experience project");
    }
    workflows::run_init(workflows::InitArgs {
        path: place_root,
        with: Vec::new(),
        preview: false,
    })?;
    places.insert(
        alias.clone(),
        json!({ "placeId": place_id, "name": name, "root": relative_root.clone() }),
    );
    let order = manifest
        .get_mut("placeOrder")
        .and_then(Value::as_array_mut)
        .context("Experience placeOrder must be an array")?;
    if place_id > 0 {
        order.push(json!(place_id));
    }
    manifest["version"] = json!(2);
    if manifest_game_id == 0 && game_id > 0 {
        manifest["gameId"] = json!(game_id);
    }
    automation_write_experience(&manifest_path, &manifest)?;
    Ok(json!({ "alias": alias, "placeId": place_id, "root": relative_root }))
}

fn automation_place_rename(
    context: &automation::BoundContext,
    parameters: &Value,
) -> Result<Value> {
    let object = parameters.as_object().context("p must be an object")?;
    let place_id = object
        .get("placeId")
        .and_then(Value::as_i64)
        .context("place-rename requires p.placeId")?;
    let requested = automation_string(object, "alias").context("place-rename requires p.alias")?;
    let alias = automation_place_alias(&requested, place_id);
    let (path, mut manifest) = automation_read_experience(context)?;
    let places = manifest
        .get_mut("places")
        .and_then(Value::as_object_mut)
        .context("Experience places must be an object")?;
    if places.contains_key(&alias) {
        bail!("Place alias {alias} already exists");
    }
    let current = places
        .iter()
        .find_map(|(name, place)| {
            (place.get("placeId").and_then(Value::as_i64) == Some(place_id)).then(|| name.clone())
        })
        .context("place-rename placeId is not configured")?;
    if current == alias {
        return Ok(json!({ "alias": alias, "placeId": place_id }));
    }
    let mut place = places
        .remove(&current)
        .expect("configured place disappeared");
    let old_root = place
        .get("root")
        .and_then(Value::as_str)
        .context("Place root is missing")?
        .to_string();
    let expected_old = format!("places/{current}");
    if old_root.replace('\\', "/") == expected_old {
        let new_root = format!("places/{alias}");
        let source = Path::new(&context.experience).join(&old_root);
        let destination = Path::new(&context.experience).join(&new_root);
        if destination.exists() {
            bail!("Place root {} already exists", destination.display());
        }
        fs::rename(&source, &destination)
            .with_context(|| format!("Failed to rename {}", source.display()))?;
        place["root"] = Value::String(new_root);
    }
    places.insert(alias.clone(), place);
    if manifest.get("startPlace").and_then(Value::as_str) == Some(&current) {
        manifest["startPlace"] = Value::String(alias.clone());
    }
    automation_write_experience(&path, &manifest)?;
    Ok(json!({ "alias": alias, "placeId": place_id }))
}

fn automation_place_reorder(
    context: &automation::BoundContext,
    parameters: &Value,
) -> Result<Value> {
    let requested = parameters
        .get("order")
        .and_then(Value::as_array)
        .context("place-reorder requires p.order")?;
    let order = requested
        .iter()
        .map(|value| value.as_i64().context("p.order must contain place IDs"))
        .collect::<Result<Vec<_>>>()?;
    let (path, mut manifest) = automation_read_experience(context)?;
    let configured = manifest
        .get("places")
        .and_then(Value::as_object)
        .context("Experience places must be an object")?
        .values()
        .filter_map(|place| place.get("placeId").and_then(Value::as_i64))
        .filter(|id| *id > 0)
        .collect::<HashSet<_>>();
    let requested_set = order.iter().copied().collect::<HashSet<_>>();
    if order.len() != requested_set.len() || requested_set != configured {
        bail!("p.order must contain every configured published place ID exactly once");
    }
    manifest["placeOrder"] = serde_json::to_value(&order)?;
    automation_write_experience(&path, &manifest)?;
    Ok(json!({ "order": order }))
}

fn automation_requires_runtime(operation: u16, parameters: &Value) -> bool {
    matches!(operation, 10..=16 | 44 | 53..=66)
        || matches!(operation, 31 | 36)
            && parameters.get("editor").and_then(Value::as_bool) == Some(true)
}

fn automation_dispatch_operation(
    operation: u16,
    context: &automation::BoundContext,
    parameters: &Value,
    bridge: &BridgeServer,
    bridge_wait_seconds: f64,
    reviewed: bool,
) -> Result<Value> {
    if automation_requires_runtime(operation, parameters) && context.runtime_id.is_none() {
        bail!("No Studio runtime is bound to this context");
    }
    let _selection = select_automation_context(context);
    bridge.clear_runtime_pins();
    match operation {
        10 | 44 => {
            let target = BridgeTarget::Main;
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, target)?;
            let info = bridge.cached_bridge_info_for_target(target)?;
            export_snapshots_with_warm_bridge(
                automation_pull_args(context, parameters, operation == 10)?,
                bridge,
                &info,
                0.0,
                false,
            )?;
            Ok(
                json!({ "direction": if operation == 10 { "studio-to-files" } else { "snapshots" } }),
            )
        }
        11 => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
            Ok(Value::Object(push_editor_changes_with_warm_bridge(
                automation_push_args(context, parameters, reviewed)?,
                bridge,
            )?))
        }
        12..=16 => {
            if operation != 14 {
                wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
            }
            let mut arguments = automation_payload_args(parameters)?;
            match operation {
                13 => arguments.push("--stop".to_string()),
                14 => arguments.push("--no-start".to_string()),
                15 => {}
                16 => arguments.push("--clear-pending".to_string()),
                _ => {}
            }
            studio_change_state_result(
                parse_daemon_request_args("studio-change-state", &arguments)?,
                bridge,
            )
        }
        31 if parameters.get("editor").and_then(Value::as_bool) == Some(true) => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
            Ok(Value::Object(apply_editor_property_with_warm_bridge(
                automation_editor_property_args(context, parameters, reviewed)?,
                bridge,
            )?))
        }
        36 if parameters.get("editor").and_then(Value::as_bool) == Some(true) => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
            Ok(Value::Object(apply_editor_delete_with_warm_bridge(
                automation_editor_delete_args(context, parameters)?,
                bridge,
            )?))
        }
        20 | 21 | 22 | 30..=37 | 40..=43 | 45 | 70 | 71 => {
            automation_spawn_cli(operation, context, parameters)
        }
        52 => {
            let file = parameters
                .get("file")
                .and_then(Value::as_str)
                .map(PathBuf::from)
                .map(|file| automation_context_path(context, file));
            workflows::launch_studio(file.as_deref(), Some(Path::new(&context.project)))
        }
        53 => {
            #[cfg(any(windows, target_os = "macos"))]
            {
                wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
                let pid = studio_pid_for_bridge(bridge)?;
                input_inject::terminate_studio_process(pid)?;
                Ok(json!({ "closed": true, "pid": pid }))
            }
            #[cfg(not(any(windows, target_os = "macos")))]
            bail!("Studio close is unsupported on this platform")
        }
        23 => automation_batch(context, parameters),
        50 | 51 => Ok(json!({
            "studios": automation_studio_candidates(
                bridge,
                if parameters.get("all").and_then(Value::as_bool) == Some(true) { "" } else { &context.selector },
            ),
            "selected": context.runtime_id,
        })),
        54 => {
            let arguments = automation_bridge_args(parameters, &[])?;
            let mut parsed: ExecuteLuauArgs =
                parse_daemon_request_args("execute-luau", &arguments)?;
            if let Some(file) = parsed.file.take() {
                parsed.file = Some(automation_context_path(context, file));
            }
            let target = if parsed.client || parsed.player.is_some() {
                BridgeTarget::Client
            } else {
                BridgeTarget::Main
            };
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, target)?;
            execute_luau_result(parsed, bridge)
        }
        55 => {
            let arguments = automation_bridge_args(parameters, &[])?;
            let parsed: PluginConsoleOutputArgs =
                parse_daemon_request_args("get-console-output", &arguments)?;
            let target = if parsed.client || parsed.player.is_some() {
                BridgeTarget::Client
            } else {
                BridgeTarget::Main
            };
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, target)?;
            get_console_output_result(&parsed, bridge)
        }
        56 if parameters.get("test").and_then(Value::as_bool) == Some(true) => {
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
            timed_test_result(
                parse_daemon_request_args("test", &automation_payload_args(parameters)?)?,
                bridge,
            )
        }
        56 | 57 => {
            let mut arguments = automation_payload_args(parameters)?;
            arguments.push(if operation == 56 { "--start" } else { "--stop" }.to_string());
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Main)?;
            start_stop_play_result(
                parse_daemon_request_args("start-stop-play", &arguments)?,
                bridge,
            )
        }
        58 => {
            let arguments = automation_bridge_args(parameters, &[])?;
            let mut parsed: ShotArgs = parse_daemon_request_args("shot", &arguments)?;
            parsed.output = automation_context_path(context, parsed.output);
            let target = if parsed.studio {
                BridgeTarget::Edit
            } else if parsed.client || parsed.player.is_some() {
                BridgeTarget::Client
            } else {
                BridgeTarget::Main
            };
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, target)?;
            shot_result(&parsed, bridge)
        }
        59 => {
            let arguments = automation_bridge_args(parameters, &["action", "device"])?;
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Edit)?;
            studio_device_result(
                &parse_daemon_request_args("studio-device", &arguments)?,
                bridge,
            )
        }
        60 => {
            let arguments = automation_bridge_args(parameters, &[])?;
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Client)?;
            ui_result(&parse_daemon_request_args("ui", &arguments)?, bridge)
        }
        61 => {
            let arguments = automation_bridge_args(parameters, &["path"])?;
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Client)?;
            press_result(&parse_daemon_request_args("press", &arguments)?, bridge)
        }
        62 => {
            let arguments = automation_bridge_args(parameters, &["x", "y"])?;
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Client)?;
            click_result(&parse_daemon_request_args("click", &arguments)?, bridge)
        }
        63 => {
            let arguments = automation_bridge_args(parameters, &["key"])?;
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Client)?;
            key_result(&parse_daemon_request_args("key", &arguments)?, bridge)
        }
        64 => {
            let arguments = automation_bridge_args(parameters, &["text"])?;
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Client)?;
            type_result(&parse_daemon_request_args("type", &arguments)?, bridge)
        }
        65 => {
            let arguments = automation_bridge_args(parameters, &["condition"])?;
            let parsed: WaitUntilArgs = parse_daemon_request_args("wait-until", &arguments)?;
            let target = if parsed.client || parsed.player.is_some() {
                BridgeTarget::Client
            } else {
                BridgeTarget::Main
            };
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, target)?;
            wait_until_result(&parsed, bridge)
        }
        66 => {
            let arguments = automation_bridge_args(parameters, &["target"])?;
            wait_for_daemon_bridge_channels(bridge, bridge_wait_seconds, BridgeTarget::Client)?;
            goto_result(&parse_daemon_request_args("goto", &arguments)?, bridge)
        }
        72 => automation_place_add(context, parameters),
        73 => automation_place_rename(context, parameters),
        74 => automation_place_reorder(context, parameters),
        _ => bail!("Unsupported automation opcode {operation}"),
    }
}

fn automation_dispatch_with_retry(
    operation: u16,
    context: &automation::BoundContext,
    parameters: &Value,
    bridge: &BridgeServer,
    bridge_wait_seconds: f64,
    reviewed: bool,
) -> std::result::Result<Value, automation::Failure> {
    let check_result = |result: Value| {
        let protected_count = result
            .get("protectedWrites")
            .and_then(Value::as_array)
            .map_or(0, Vec::len);
        if !reviewed && matches!(operation, 11 | 31) && protected_count > 0 {
            return Err(automation::Failure::new(
                "rejected",
                "Protected property fallback requires a review receipt",
                false,
                "review-prepare",
            )
            .detail(json!({ "protectedWrites": protected_count })));
        }
        Ok(result)
    };
    let first = automation_dispatch_operation(
        operation,
        context,
        parameters,
        bridge,
        bridge_wait_seconds,
        reviewed,
    )
    .map_err(automation_failure)
    .and_then(&check_result);
    match first {
        Err(failure) if failure.0.rt == 1 => automation_dispatch_operation(
            operation,
            context,
            parameters,
            bridge,
            bridge_wait_seconds,
            reviewed,
        )
        .map_err(automation_failure)
        .and_then(check_result),
        result => result,
    }
}

fn automation_execute_request(
    request: &automation::Request,
    state: &automation::State,
    bridge: &BridgeServer,
    bridge_wait_seconds: f64,
) -> std::result::Result<Value, automation::Failure> {
    let operation = request.validate()?;
    match operation.id {
        0 => automation::capabilities().map_err(automation_failure),
        1 => automation_bind(state, bridge, &request.p),
        _ => {
            let context_id = request
                .cx
                .expect("validated requests after bind require cx");
            if operation.id == 3 {
                return Ok(json!({ "removed": state.remove_context(context_id) }));
            }
            let context = automation_context(state, bridge, context_id)?;
            if operation.id == 2 {
                return serde_json::to_value(context).map_err(|error| {
                    automation::Failure::new("internal", error.to_string(), false, "bind")
                });
            }
            if !context.initialized && !matches!(operation.id, 70 | 71) {
                return Err(automation::Failure::new(
                    "no_project",
                    "This bootstrap context can only initialize or validate its project",
                    false,
                    "project-init",
                ));
            }
            if operation.id == 80 {
                let object = automation_object(&request.p)?;
                let target = object
                    .get("op")
                    .and_then(Value::as_u64)
                    .and_then(|value| u16::try_from(value).ok())
                    .ok_or_else(|| {
                        automation::Failure::new(
                            "bad_req",
                            "review-prepare requires numeric p.op",
                            false,
                            "cap",
                        )
                    })?;
                let target_operation = automation::opcode_by_id(target).map_err(|_| {
                    automation::Failure::new(
                        "bad_op",
                        format!("Unknown opcode {target}"),
                        false,
                        "cap",
                    )
                })?;
                if !target_operation.review {
                    return Err(automation::Failure::new(
                        "bad_req",
                        format!("{} does not require review", target_operation.name),
                        false,
                        "cap",
                    ));
                }
                let parameters = object.get("p").cloned().unwrap_or_else(|| json!({}));
                if !parameters.is_object() {
                    return Err(automation::Failure::new(
                        "bad_req",
                        "review-prepare p.p must be an object",
                        false,
                        "review-prepare",
                    ));
                }
                let review_id = state.prepare_review(&context, target, parameters);
                return Ok(
                    json!({ "reviewId": review_id, "op": target, "name": target_operation.name }),
                );
            }
            if operation.id == 82 {
                let review_id = request
                    .p
                    .get("reviewId")
                    .and_then(Value::as_str)
                    .ok_or_else(|| {
                        automation::Failure::new(
                            "bad_req",
                            "review-reject requires p.reviewId",
                            false,
                            "review-prepare",
                        )
                    })?;
                return Ok(json!({ "rejected": state.reject_review(review_id) }));
            }
            if operation.id == 81 {
                if request.p.get("studioDecision").and_then(Value::as_bool) == Some(true) {
                    if context.runtime_id.is_none() {
                        return Err(automation::Failure::new(
                            "no_studio",
                            "No Studio runtime is bound to this context",
                            false,
                            "studios",
                        ));
                    }
                    let _selection = select_automation_context(&context);
                    bridge.clear_runtime_pins();
                    wait_for_daemon_bridge_channels(
                        bridge,
                        bridge_wait_seconds,
                        BridgeTarget::Main,
                    )
                    .map_err(automation_failure)?;
                    let args = parse_daemon_request_args::<EditorReviewDecisionArgs>(
                        "editor-review-decision",
                        &automation_payload_args(&request.p).map_err(automation_failure)?,
                    )
                    .map_err(automation_failure)?;
                    return editor_review_decision_result(&args, bridge)
                        .map_err(automation_failure);
                }
                let review_id = request
                    .p
                    .get("reviewId")
                    .and_then(Value::as_str)
                    .ok_or_else(|| {
                        automation::Failure::new(
                            "bad_req",
                            "review-apply requires p.reviewId",
                            false,
                            "review-prepare",
                        )
                    })?;
                let review = state.take_review(review_id).ok_or_else(|| {
                    automation::Failure::new(
                        "rejected",
                        "Review receipt is invalid or expired",
                        false,
                        "review-prepare",
                    )
                })?;
                if review.context_id != context.id || review.runtime_id != context.runtime_id {
                    return Err(automation::Failure::new(
                        "rejected",
                        "Review receipt does not match this context",
                        false,
                        "review-prepare",
                    ));
                }
                return automation_dispatch_with_retry(
                    review.operation,
                    &context,
                    &review.parameters,
                    bridge,
                    bridge_wait_seconds,
                    true,
                );
            }
            let requires_review = operation.review
                && (matches!(operation.id, 52 | 53)
                    || request.p.get("destructive").and_then(Value::as_bool) == Some(true));
            if requires_review {
                return Err(automation::Failure::new(
                    "rejected",
                    "This operation requires a review receipt",
                    false,
                    "review-prepare",
                ));
            }
            automation_dispatch_with_retry(
                operation.id,
                &context,
                &request.p,
                bridge,
                bridge_wait_seconds,
                false,
            )
        }
    }
}

fn automation_response(
    request: automation::Request,
    state: &automation::State,
    bridge: &BridgeServer,
    bridge_wait_seconds: f64,
) -> automation::Response {
    let started = Instant::now();
    let result = if matches!(request.op, 0 | 1 | 2 | 3 | 50 | 51 | 80 | 82) {
        automation_execute_request(&request, state, bridge, bridge_wait_seconds)
    } else {
        bridge
            .acquire_request_gate(DAEMON_CONTROL_QUEUE_TIMEOUT)
            .map_err(automation_failure)
            .and_then(|_guard| {
                automation_execute_request(&request, state, bridge, bridge_wait_seconds)
            })
    };
    match result {
        Ok(result) => automation::Response::success(request.id, started, result),
        Err(failure) => automation::Response::failure(request.id, started, failure),
    }
}

fn automation_parse_response(
    text: &str,
    state: &automation::State,
    bridge: &BridgeServer,
    bridge_wait_seconds: f64,
) -> automation::Response {
    let started = Instant::now();
    match serde_json::from_str::<automation::Request>(text) {
        Ok(request) => automation_response(request, state, bridge, bridge_wait_seconds),
        Err(error) => automation::Response::failure(
            0,
            started,
            automation::Failure::new(
                "bad_req",
                format!("Invalid request JSON: {error}"),
                false,
                "cap",
            ),
        ),
    }
}

fn run_automation_stdio(
    bridge: &BridgeServer,
    state: &automation::State,
    bridge_wait_seconds: f64,
) -> Result<()> {
    let stdin = io::stdin();
    let mut reader = stdin.lock();
    let mut line = String::new();
    loop {
        match read_bounded_line(&mut reader, &mut line, MAX_DAEMON_LINE_BYTES)? {
            BoundedLineRead::Eof => break,
            BoundedLineRead::Line => {
                let trimmed = line.trim();
                if trimmed.is_empty() {
                    continue;
                }
                let response =
                    automation_parse_response(trimmed, state, bridge, bridge_wait_seconds);
                std::println!("{}", serde_json::to_string(&response)?);
                io::stdout().flush()?;
            }
            BoundedLineRead::TooLong => {
                let response = automation::Response::failure(
                    0,
                    Instant::now(),
                    automation::Failure::new(
                        "bad_req",
                        format!("Request exceeds {MAX_DAEMON_LINE_BYTES} bytes"),
                        false,
                        "cap",
                    ),
                );
                std::println!("{}", serde_json::to_string(&response)?);
                io::stdout().flush()?;
            }
        }
    }
    Ok(())
}

fn bridge_daemon(args: BridgeDaemonArgs) -> Result<()> {
    let editor_stdio = args.editor_stdio;
    AUTOMATION_STDIO.store(editor_stdio, Ordering::Relaxed);
    let name = args
        .name
        .or_else(|| std::env::var("RENIUM_DAEMON_NAME").ok())
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "default".to_string());
    if let Some(parent_pid) = args.parent_pid {
        watch_parent_and_exit(parent_pid);
    }
    let lifecycle_lock = lifecycle::acquire_lifecycle_lock()?;
    let bridge_host = normalize_loopback_bridge_host(&args.bridge_host)?;
    let ports = parse_bridge_ports(&args.bridge_ports)?;
    let (bridge, listen_metrics) = BridgeServer::listen_with_initial_wait(
        &bridge_host,
        &ports,
        args.bridge_wait_seconds,
        false,
    )?;
    let bridge = Arc::new(bridge);
    let automation_state = Arc::new(automation::State::default());
    if !editor_stdio {
        spawn_daemon_control_server(
            bridge_host.clone(),
            args.control_port,
            name.clone(),
            bridge.clone(),
            automation_state.clone(),
            args.bridge_wait_seconds,
        )?;
        write_daemon_discovery_file(&name, &bridge_host, args.control_port, &ports)?;
    }
    drop(lifecycle_lock);

    println!(
        "[renium] daemon ready: channels={}/{}, bind_ms={:.1}, warmup_handshake_ms={:.1}",
        bridge.channel_count(),
        bridge.expected_channel_count(),
        listen_metrics.bind_ms,
        listen_metrics.wait_for_channels_ms
    );
    if editor_stdio {
        run_automation_stdio(&bridge, &automation_state, args.bridge_wait_seconds)?;
        bridge.alive.store(false, Ordering::Relaxed);
        return Ok(());
    }
    while bridge.alive.load(Ordering::Relaxed) {
        thread::sleep(Duration::from_millis(250));
    }
    bridge.alive.store(false, Ordering::Relaxed);
    println!("[renium] daemon stopped");
    Ok(())
}

fn spawn_daemon_control_server(
    host: String,
    port: u16,
    name: String,
    bridge: Arc<BridgeServer>,
    state: Arc<automation::State>,
    bridge_wait_seconds: f64,
) -> Result<()> {
    let bind_host = normalize_loopback_bridge_host(&host)?;
    let listener = TcpListener::bind((bind_host.as_str(), port)).with_context(|| {
        let discoveries = daemon_discovery_write_paths(&name)
        .into_iter()
        .map(|path| path.display().to_string())
        .collect::<Vec<_>>()
        .join(", ");
        format!(
            "Failed to bind daemon control on {bind_host}:{port}; check {discoveries}, then run `rbx daemon clean` or choose another --control-port"
        )
    })?;
    println!(
        "[renium] daemon control listening on {}:{}",
        bind_host, port
    );
    let active_connections = Arc::new(AtomicUsize::new(0));
    thread::spawn(move || {
        while bridge.alive.load(Ordering::Relaxed) {
            match listener.accept() {
                Ok((stream, _addr)) => {
                    let previous = active_connections.fetch_add(1, Ordering::Relaxed);
                    if previous >= MAX_DAEMON_CONTROL_CONNECTIONS {
                        active_connections.fetch_sub(1, Ordering::Relaxed);
                        eprintln!(
                            "[renium] warning: rejecting daemon control connection; {} connection limit reached",
                            MAX_DAEMON_CONTROL_CONNECTIONS
                        );
                        continue;
                    }
                    let _ = stream.set_nonblocking(false);
                    let bridge = bridge.clone();
                    let state = state.clone();
                    let active_connections = active_connections.clone();
                    thread::spawn(move || {
                        let result = handle_daemon_control_connection(
                            stream,
                            &bridge,
                            &state,
                            bridge_wait_seconds,
                        );
                        active_connections.fetch_sub(1, Ordering::Relaxed);
                        if let Err(err) = result {
                            eprintln!("[renium] daemon control error: {err:#}");
                        }
                    });
                }
                Err(err) => {
                    if bridge.alive.load(Ordering::Relaxed) {
                        println!("[renium] warning: daemon control accept failed: {err}");
                        thread::sleep(Duration::from_millis(25));
                    }
                }
            }
        }
    });
    Ok(())
}

fn handle_daemon_control_connection(
    stream: TcpStream,
    bridge: &BridgeServer,
    state: &automation::State,
    bridge_wait_seconds: f64,
) -> Result<()> {
    let _ = stream.set_read_timeout(Some(DAEMON_CONTROL_IDLE_TIMEOUT));
    let _ = stream.set_write_timeout(Some(DAEMON_CONTROL_IDLE_TIMEOUT));
    let reader_stream = stream
        .try_clone()
        .context("Failed to clone control stream")?;
    let mut reader = BufReader::new(reader_stream);
    let mut writer = BufWriter::new(stream);
    let mut line = String::new();
    loop {
        match read_bounded_line(&mut reader, &mut line, MAX_DAEMON_LINE_BYTES)
            .context("Failed to read daemon control request")?
        {
            BoundedLineRead::Eof => break,
            BoundedLineRead::Line => {}
            BoundedLineRead::TooLong => {
                let response = automation::Response::failure(
                    0,
                    Instant::now(),
                    automation::Failure::new(
                        "bad_req",
                        format!("Request exceeds {MAX_DAEMON_LINE_BYTES} bytes"),
                        false,
                        "cap",
                    ),
                );
                writeln!(writer, "{}", serde_json::to_string(&response)?)?;
                writer.flush()?;
                continue;
            }
        }
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let response = automation_parse_response(trimmed, state, bridge, bridge_wait_seconds);
        writeln!(writer, "{}", serde_json::to_string(&response)?)?;
        writer.flush()?;
    }
    Ok(())
}

fn wait_for_daemon_bridge_channels(
    bridge: &BridgeServer,
    bridge_wait_seconds: f64,
    target: BridgeTarget,
) -> Result<()> {
    let required_channels = bridge.expected_channel_count();
    let ready_channels = bridge.wait_for_ready_channels_for_target(
        required_channels,
        Duration::from_secs_f64(bridge_wait_seconds.max(1.0)),
        target,
    );
    if ready_channels < required_channels {
        bail!(
            "Only {}/{} persistent {} plugin bridge channels are ready{}. Missing ports: {:?}",
            ready_channels,
            required_channels,
            BridgeServer::target_label(target),
            place_filter()
                .map(|place| format!(" for place filter '{place}'"))
                .unwrap_or_default(),
            bridge.missing_ports_for_target(target)
        );
    }
    let bridge_info = bridge.cached_bridge_info_for_target(target)?;
    validate_bridge_info(&bridge_info)?;
    Ok(())
}

fn bridge_get_source(args: BridgeGetSourceArgs) -> Result<()> {
    let ports = parse_bridge_ports(&args.bridge_ports)?;
    let (bridge, listen_metrics) =
        BridgeServer::listen(&args.bridge_host, &ports, args.bridge_wait_seconds)?;
    let source = bridge_fetch_source(
        &bridge,
        &args.service,
        &args.source_key,
        clamp_bridge_chunk_size(args.chunk_size),
    )?;
    let expected = match &args.expect_file {
        Some(path) => Some(
            fs::read_to_string(path)
                .with_context(|| format!("Failed to read expected file {}", path.display()))?,
        ),
        None => None,
    };
    let matches_expected = expected.as_ref().is_none_or(|expected| expected == &source);
    let summary = json!({
        "ok": matches_expected,
        "service": args.service,
        "sourceKey": args.source_key,
        "sourceLen": source.len(),
        "sourceHash": fnv1a64_hex(source.as_bytes()),
        "expectedLen": expected.as_ref().map(String::len),
        "expectedHash": expected.as_ref().map(|value| fnv1a64_hex(value.as_bytes())),
        "matchesExpected": matches_expected,
        "channels": bridge.channel_count(),
        "handshakeMs": listen_metrics.wait_for_channels_ms,
    });
    println!("__ROBLOX_SYNC_BRIDGE_SOURCE_RESULT__ {summary}");
    if !matches_expected {
        bail!("Studio source did not match expected file");
    }
    Ok(())
}

fn bridge_fetch_source(
    bridge: &BridgeServer,
    service: &str,
    source_key: &str,
    chunk_size: usize,
) -> Result<String> {
    let (source, _) = fetch_text_chunks(chunk_size, |start_index, max_len| {
        bridge.call_chunk(
            "getSourceChunk",
            json!({
                "service": service,
                "instancePath": source_key,
                "startIndex": start_index,
                "maxLen": max_len,
            }),
        )
    })?;
    Ok(source)
}

fn write_daemon_discovery_file(
    name: &str,
    host: &str,
    control_port: u16,
    bridge_ports: &[u16],
) -> Result<()> {
    let bind_host = normalize_loopback_bridge_host(host)?;
    let process_start_identity = lifecycle::process_start_identity(std::process::id())
        .context("Could not read the daemon process start identity")?;
    let payload = json!({
        "schemaVersion": 2,
        "name": name,
        "host": bind_host,
        "controlPort": control_port,
        "bridgePorts": bridge_ports,
        "pid": std::process::id(),
        "processStartIdentity": process_start_identity,
        "updatedUnixMs": current_millis(),
    });
    let mut text = serde_json::to_vec_pretty(&payload)?;
    text.push(b'\n');
    let paths = daemon_discovery_write_paths(name);
    if paths.is_empty() {
        bail!("No daemon discovery path is available");
    }
    let mut errors = Vec::new();
    for path in paths {
        if let Err(error) = lifecycle::install_bytes(&path, &text) {
            errors.push(format!("{}: {error:#}", path.display()));
        }
    }
    if !errors.is_empty() {
        bail!(
            "Could not publish Renium daemon discovery: {}",
            errors.join("; ")
        );
    }
    Ok(())
}

fn daemon_discovery_write_paths(name: &str) -> Vec<PathBuf> {
    if let Ok(path) = std::env::var("RENIUM_DAEMON_FILE") {
        let path = path.trim();
        if !path.is_empty() {
            return vec![PathBuf::from(path)];
        }
    }
    let Some(default) = local_app_data_daemon_path() else {
        return Vec::new();
    };
    if name == "default" {
        return vec![default];
    }
    let safe_name = name
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_') {
                ch
            } else {
                '_'
            }
        })
        .collect::<String>();
    vec![default.with_file_name(format!("daemon-{safe_name}.json"))]
}

fn daemon_control_endpoints() -> Vec<std::net::SocketAddr> {
    let mut out = Vec::new();
    let mut seen = HashSet::new();

    if let Ok(raw) = std::env::var("RENIUM_DAEMON") {
        push_daemon_endpoint(&mut out, &mut seen, raw.trim());
    }

    let env_host = std::env::var("RENIUM_DAEMON_HOST").unwrap_or_else(|_| "127.0.0.1".to_string());
    if let Ok(raw_port) = std::env::var("RENIUM_DAEMON_CONTROL_PORT")
        && let Ok(port) = raw_port.trim().parse::<u16>()
    {
        push_daemon_endpoint(
            &mut out,
            &mut seen,
            &loopback_host_port(env_host.trim(), port),
        );
    }

    for path in daemon_discovery_paths() {
        if let Ok(text) = fs::read_to_string(&path)
            && let Ok(value) = serde_json::from_str::<Value>(&text)
            && let Some(endpoint) = daemon_discovery_endpoint(&value)
        {
            let key = endpoint.to_string();
            if seen.insert(key) {
                out.push(endpoint);
            }
        }
    }

    push_daemon_endpoint(
        &mut out,
        &mut seen,
        &loopback_host_port("127.0.0.1", DEFAULT_DAEMON_CONTROL_PORT),
    );
    out
}

fn daemon_discovery_paths() -> Vec<PathBuf> {
    let mut paths = Vec::new();
    if let Ok(path) = std::env::var("RENIUM_DAEMON_FILE") {
        let path = path.trim();
        if !path.is_empty() {
            paths.push(PathBuf::from(path));
        }
    }
    if let Some(path) = local_app_data_daemon_path() {
        if let Ok(name) = std::env::var("RENIUM_DAEMON_NAME") {
            let name = name.trim();
            if !name.is_empty() && name != "default" {
                let safe_name = name
                    .chars()
                    .map(|ch| {
                        if ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_') {
                            ch
                        } else {
                            '_'
                        }
                    })
                    .collect::<String>();
                paths.push(path.with_file_name(format!("daemon-{safe_name}.json")));
                return paths;
            }
        }
        paths.push(path);
    }
    paths
}

fn local_app_data_daemon_path() -> Option<PathBuf> {
    if let Some(base) = std::env::var_os("LOCALAPPDATA") {
        return Some(PathBuf::from(base).join("Renium").join("daemon.json"));
    }
    let home = std::env::var_os("HOME")?;
    Some(PathBuf::from(home).join(".renium").join("daemon.json"))
}

fn daemon_discovery_endpoint(value: &Value) -> Option<std::net::SocketAddr> {
    let schema_version = value.get("schemaVersion").and_then(Value::as_u64);
    if schema_version != Some(2) {
        return None;
    }
    let host = normalize_loopback_bridge_host(value.get("host")?.as_str()?).ok()?;
    let port = value
        .get("controlPort")
        .and_then(Value::as_u64)
        .and_then(|value| u16::try_from(value).ok())?;
    if port == 0 {
        return None;
    }
    let pid = value
        .get("pid")
        .and_then(Value::as_u64)
        .and_then(|value| u32::try_from(value).ok())?;
    let process_start_identity = value.get("processStartIdentity")?.as_str()?;
    let updated_ms = value.get("updatedUnixMs").and_then(Value::as_u64)? as u128;
    let now = current_millis();
    if updated_ms > now.saturating_add(DAEMON_DISCOVERY_MAX_FUTURE_SKEW_MS)
        || now.saturating_sub(updated_ms) > DAEMON_DISCOVERY_MAX_AGE_MS
        || !is_process_alive(pid)
        || lifecycle::process_start_identity(pid).as_deref() != Some(process_start_identity)
    {
        return None;
    }
    loopback_host_port(&host, port)
        .to_socket_addrs()
        .ok()?
        .find(is_loopback_endpoint)
}

fn is_process_alive(pid: u32) -> bool {
    if pid == 0 {
        return false;
    }
    #[cfg(windows)]
    unsafe {
        use windows_sys::Win32::Foundation::CloseHandle;
        use windows_sys::Win32::System::Threading::{
            OpenProcess, PROCESS_SYNCHRONIZE, WaitForSingleObject,
        };

        let handle = OpenProcess(PROCESS_SYNCHRONIZE, 0, pid);
        if handle.is_null() {
            return false;
        }
        let alive = WaitForSingleObject(handle, 0) == 0x0000_0102;
        CloseHandle(handle);
        alive
    }
    #[cfg(not(windows))]
    {
        unsafe {
            libc::kill(pid as libc::pid_t, 0) == 0
                || io::Error::last_os_error().raw_os_error() == Some(libc::EPERM)
        }
    }
}

fn push_daemon_endpoint(
    out: &mut Vec<std::net::SocketAddr>,
    seen: &mut HashSet<String>,
    raw: &str,
) {
    let text = raw.trim();
    if text.is_empty() {
        return;
    }
    if let Ok(address) = text.parse::<std::net::SocketAddr>() {
        if !is_loopback_endpoint(&address) {
            return;
        }
        let key = address.to_string();
        if seen.insert(key) {
            out.push(address);
        }
        return;
    }
    if let Ok(addresses) = text.to_socket_addrs() {
        for address in addresses {
            if !is_loopback_endpoint(&address) {
                continue;
            }
            let key = address.to_string();
            if seen.insert(key) {
                out.push(address);
            }
        }
    }
}

fn try_daemon_control_request(command: &str, args: Vec<String>) -> Result<Option<Value>> {
    if daemon_control_endpoints().into_iter().all(|address| {
        TcpStream::connect_timeout(&address, DAEMON_CONTROL_CONNECT_TIMEOUT).is_err()
    }) {
        return Ok(None);
    }
    let has = |needle: &str| args.iter().any(|argument| argument == needle);
    let explicitly_approved = (has("--yes") || has("--apply")) && !has("--no-review");
    let (operation, mut parameters) = match command {
        "x" | "export" | "export-snapshots" => (
            if has("-i") || has("--run-import") {
                10
            } else {
                44
            },
            json!({ "a": args }),
        ),
        "push" | "push-editor-changes" => {
            let incremental = has("-p")
                || has("--changed-path")
                || has("-f")
                || has("--changed-paths-file")
                || has("-i")
                || has("--target-settings-id")
                || has("-t")
                || has("--target-property");
            (11, json!({ "a": args, "destructive": !incremental }))
        }
        "prop" | "apply-editor-property" => (31, json!({ "a": args, "editor": true })),
        "del" | "apply-editor-delete" => (36, json!({ "a": args, "editor": true })),
        "co" | "console" | "get-console-output" => (55, json!({ "a": args })),
        "lx" | "luau" | "execute-luau" => (54, json!({ "a": args })),
        "device" | "dev" | "studio-device" => (59, json!({ "a": args })),
        "play" | "start-stop-play" => (
            if has("-x") || has("--stop") { 57 } else { 56 },
            json!({ "a": args }),
        ),
        "test" => (56, json!({ "a": args, "test": true })),
        "review" | "editor-review-decision" => (81, json!({ "a": args, "studioDecision": true })),
        "clients" | "list-clients" => (50, json!({})),
        "press" => (61, json!({ "a": args })),
        "click" => (62, json!({ "a": args })),
        "key" => (63, json!({ "a": args })),
        "ui" => (60, json!({ "a": args })),
        "type" => (64, json!({ "a": args })),
        "wait-until" => (65, json!({ "a": args })),
        "goto" => (66, json!({ "a": args })),
        "shot" => (58, json!({ "a": args })),
        "st" | "studio-change-state" => (
            if has("--stop") {
                13
            } else if has("--no-start") {
                14
            } else {
                12
            },
            json!({ "a": args }),
        ),
        _ => return Ok(None),
    };
    let root = parameters
        .get("a")
        .and_then(Value::as_array)
        .and_then(|arguments| {
            arguments.iter().enumerate().find_map(|(index, argument)| {
                matches!(argument.as_str(), Some("-r" | "--root" | "--project-root"))
                    .then(|| {
                        arguments
                            .get(index + 1)
                            .and_then(Value::as_str)
                            .map(str::to_string)
                    })
                    .flatten()
            })
        })
        .unwrap_or_else(|| {
            std::env::current_dir()
                .unwrap_or_else(|_| PathBuf::from("."))
                .display()
                .to_string()
        });
    let bind = send_automation_control_request(&automation::Request {
        v: automation::PROTOCOL_VERSION,
        id: current_millis().min(u128::from(u64::MAX)) as u64,
        op: 1,
        cx: None,
        p: json!({ "root": root, "place": place_filter() }),
    })?;
    if bind.ok == 0 {
        let error = bind.e.context("Daemon bind failed without an error")?;
        bail!("{}", error.m);
    }
    let context_id = bind
        .r
        .as_ref()
        .and_then(|result| result.get("id"))
        .and_then(Value::as_u64)
        .context("Daemon bind response omitted the context ID")?;
    let requires_review = parameters.get("destructive").and_then(Value::as_bool) == Some(true)
        || explicitly_approved && matches!(operation, 11 | 31);
    let response = if requires_review {
        let prepare = send_automation_control_request(&automation::Request {
            v: automation::PROTOCOL_VERSION,
            id: current_millis().min(u128::from(u64::MAX)) as u64,
            op: 80,
            cx: Some(context_id),
            p: json!({ "op": operation, "p": parameters }),
        })?;
        if prepare.ok == 0 {
            let error = prepare
                .e
                .context("Review preparation failed without an error")?;
            bail!("{}", error.m);
        }
        let review_id = prepare
            .r
            .as_ref()
            .and_then(|result| result.get("reviewId"))
            .and_then(Value::as_str)
            .context("Review preparation omitted reviewId")?;
        send_automation_control_request(&automation::Request {
            v: automation::PROTOCOL_VERSION,
            id: current_millis().min(u128::from(u64::MAX)) as u64,
            op: 81,
            cx: Some(context_id),
            p: json!({ "reviewId": review_id }),
        })?
    } else {
        send_automation_control_request(&automation::Request {
            v: automation::PROTOCOL_VERSION,
            id: current_millis().min(u128::from(u64::MAX)) as u64,
            op: operation,
            cx: Some(context_id),
            p: std::mem::take(&mut parameters),
        })?
    };
    if response.ok == 0 {
        let error = response
            .e
            .context("Daemon request failed without an error")?;
        bail!("{}", error.m);
    }
    Ok(Some(response.r.unwrap_or_else(|| json!({}))))
}

