fn get_console_output_command(args: PluginConsoleOutputArgs) -> Result<()> {
    if args.follow {
        if follow_console_via_daemon(&args)? {
            return Ok(());
        }
    } else if let Some(result) =
        try_daemon_control_request("co", get_console_output_daemon_args(&args))?
    {
        println!(
            "{}",
            serde_json::to_string_pretty(&filtered_console_result(&args, result))?
        );
        return Ok(());
    }
    let ports = parse_bridge_ports(&args.bridge_ports)?;
    let (bridge, _listen_metrics) =
        BridgeServer::listen(&args.bridge_host, &ports, args.bridge_wait_seconds)?;
    get_console_output_with_warm_bridge(args, &bridge)
}

fn get_console_output_with_warm_bridge(
    args: PluginConsoleOutputArgs,
    bridge: &BridgeServer,
) -> Result<()> {
    if args.follow {
        return follow_console_with_bridge(&args, bridge);
    }
    let result = get_console_output_result(&args, bridge)?;
    println!(
        "{}",
        serde_json::to_string_pretty(&filtered_console_result(&args, result))?
    );
    Ok(())
}

fn get_console_output_result(
    args: &PluginConsoleOutputArgs,
    bridge: &BridgeServer,
) -> Result<Value> {
    let client = args.client || args.player.is_some();
    let target = if client {
        BridgeTarget::Client
    } else {
        BridgeTarget::Main
    };
    if let Some(player) = args.player.as_deref() {
        wait_for_player_bridge(bridge, player, args.bridge_wait_seconds)?;
    }
    let result = bridge.call_for_selector(
        "getConsoleOutput",
        json!({
            "limit": args.limit,
            "sinceSeq": args.since_seq,
            "fromOldest": args.from_oldest,
            "clear": args.clear,
        }),
        target,
        args.player.as_deref(),
    )?;
    ensure_plugin_api_ok(&result)?;
    Ok(result)
}

fn follow_console_via_daemon(args: &PluginConsoleOutputArgs) -> Result<bool> {
    let mut since_seq = args.since_seq;
    let mut from_oldest = false;
    let mut connected = false;
    let mut epoch = None;
    loop {
        let mut request = get_console_output_daemon_args(args);
        if let Some(position) = request.iter().position(|arg| arg == "-s")
            && let Some(value) = request.get_mut(position + 1)
        {
            *value = since_seq.to_string();
        }
        if connected && let Some(position) = request.iter().position(|arg| arg == "-c") {
            request.remove(position);
        }
        if from_oldest {
            request.push("--from-oldest".to_string());
        }
        let result = match try_daemon_control_request("co", request) {
            Ok(Some(result)) => result,
            Ok(None) if connected => {
                thread::sleep(Duration::from_millis(args.interval_ms.clamp(25, 10_000)));
                continue;
            }
            Ok(None) => return Ok(false),
            Err(error) if connected && is_transient_console_follow_error(&error) => {
                thread::sleep(Duration::from_millis(args.interval_ms.clamp(25, 10_000)));
                continue;
            }
            Err(error) => return Err(error),
        };
        connected = true;
        let next_epoch = result
            .get("epoch")
            .and_then(Value::as_str)
            .map(str::to_string);
        if epoch.is_some() && next_epoch != epoch {
            since_seq = 0;
            from_oldest = true;
            epoch = next_epoch;
            continue;
        }
        epoch = next_epoch;
        print_followed_console_entries(args, &result)?;
        from_oldest = false;
        since_seq = result
            .get("nextSeq")
            .and_then(Value::as_u64)
            .unwrap_or(since_seq);
        if result.get("hasMore").and_then(Value::as_bool) != Some(true) {
            thread::sleep(Duration::from_millis(args.interval_ms.clamp(25, 10_000)));
        }
    }
}

fn follow_console_with_bridge(args: &PluginConsoleOutputArgs, bridge: &BridgeServer) -> Result<()> {
    let mut since_seq = args.since_seq;
    let mut from_oldest = false;
    let mut epoch = None;
    let mut clear_pending = args.clear;
    loop {
        let request = PluginConsoleOutputArgs {
            bridge_wait_seconds: args.bridge_wait_seconds,
            bridge_host: args.bridge_host.clone(),
            bridge_ports: args.bridge_ports.clone(),
            limit: args.limit,
            since_seq,
            from_oldest: args.from_oldest || from_oldest,
            clear: clear_pending,
            client: args.client,
            player: args.player.clone(),
            follow: false,
            grep: args.grep.clone(),
            level: args.level.clone(),
            interval_ms: args.interval_ms,
        };
        let result = match get_console_output_result(&request, bridge) {
            Ok(result) => result,
            Err(error) if is_transient_console_follow_error(&error) => {
                thread::sleep(Duration::from_millis(args.interval_ms.clamp(25, 10_000)));
                continue;
            }
            Err(error) => return Err(error),
        };
        clear_pending = false;
        let next_epoch = result
            .get("epoch")
            .and_then(Value::as_str)
            .map(str::to_string);
        if epoch.is_some() && next_epoch != epoch {
            since_seq = 0;
            from_oldest = true;
            epoch = next_epoch;
            continue;
        }
        epoch = next_epoch;
        print_followed_console_entries(args, &result)?;
        from_oldest = false;
        since_seq = result
            .get("nextSeq")
            .and_then(Value::as_u64)
            .unwrap_or(since_seq);
        if result.get("hasMore").and_then(Value::as_bool) != Some(true) {
            thread::sleep(Duration::from_millis(args.interval_ms.clamp(25, 10_000)));
        }
    }
}

fn is_transient_console_follow_error(error: &anyhow::Error) -> bool {
    if is_transient_bridge_error(error) {
        return true;
    }
    let message = error
        .chain()
        .map(|cause| cause.to_string())
        .collect::<Vec<_>>()
        .join(": ")
        .to_ascii_lowercase();
    [
        "connection reset",
        "connection refused",
        "broken pipe",
        "unexpected eof",
        "timed out",
        "daemon control endpoint is unavailable",
        "closed the control connection",
        "did not finish co before the control timeout",
    ]
    .iter()
    .any(|needle| message.contains(needle))
        && ![
            "multiple studio",
            "match this command",
            "player selector",
            "no player matched",
            "ambiguous",
        ]
        .iter()
        .any(|needle| message.contains(needle))
}

fn filtered_console_result(args: &PluginConsoleOutputArgs, mut result: Value) -> Value {
    let filtered_count =
        if let Some(entries) = result.get_mut("entries").and_then(Value::as_array_mut) {
            entries.retain(|entry| console_entry_matches(args, entry));
            entries.len()
        } else {
            return result;
        };
    if let Some(object) = result.as_object_mut() {
        object.insert("filteredCount".to_string(), json!(filtered_count));
    }
    result
}

fn print_followed_console_entries(args: &PluginConsoleOutputArgs, result: &Value) -> Result<()> {
    if result.get("truncated").and_then(Value::as_bool) == Some(true) {
        eprintln!(
            "[renium] console history was truncated; continuing from the oldest retained line"
        );
    }
    if let Some(entries) = result.get("entries").and_then(Value::as_array) {
        for entry in entries
            .iter()
            .filter(|entry| console_entry_matches(args, entry))
        {
            let level = entry
                .get("type")
                .or_else(|| entry.get("level"))
                .and_then(Value::as_str)
                .unwrap_or("output");
            let message = entry
                .get("message")
                .and_then(Value::as_str)
                .unwrap_or_default();
            println!("[{level}] {message}");
        }
    }
    io::stdout().flush()?;
    Ok(())
}

fn console_entry_matches(args: &PluginConsoleOutputArgs, entry: &Value) -> bool {
    if let Some(level) = args.level.as_deref() {
        let entry_level = entry
            .get("type")
            .or_else(|| entry.get("level"))
            .and_then(Value::as_str)
            .unwrap_or("output");
        if !entry_level.eq_ignore_ascii_case(level) {
            return false;
        }
    }
    if let Some(needle) = args.grep.as_deref() {
        let message = entry
            .get("message")
            .and_then(Value::as_str)
            .unwrap_or_default();
        if !message
            .to_ascii_lowercase()
            .contains(&needle.to_ascii_lowercase())
        {
            return false;
        }
    }
    true
}

fn execute_luau_command(args: ExecuteLuauArgs) -> Result<()> {
    if let Some(result) = try_daemon_control_request("lx", execute_luau_daemon_args(&args)?)? {
        println!("{}", serde_json::to_string_pretty(&result)?);
        return Ok(());
    }
    let ports = parse_bridge_ports(&args.bridge_ports)?;
    let target = if args.client || args.player.is_some() {
        BridgeTarget::Client
    } else {
        BridgeTarget::Main
    };
    let (bridge, _listen_metrics) = BridgeServer::listen_with_initial_wait(
        &args.bridge_host,
        &ports,
        args.bridge_wait_seconds,
        false,
    )?;
    let required_channels = bridge.expected_channel_count();
    let ready_channels = bridge.wait_for_ready_channels_for_target(
        required_channels,
        Duration::from_secs_f64(args.bridge_wait_seconds.max(1.0)),
        target,
    );
    if ready_channels < required_channels {
        bail!(
            "Only {}/{} persistent {} plugin bridge channels are ready{}. Missing ports: {:?}",
            ready_channels,
            required_channels,
            BridgeServer::target_label(target),
            place_filter()
                .map(|place| format!(" for place filter '{place}'"))
                .unwrap_or_default(),
            bridge.missing_ports_for_target(target)
        );
    }
    execute_luau_with_warm_bridge(args, &bridge)
}

fn execute_luau_with_warm_bridge(args: ExecuteLuauArgs, bridge: &BridgeServer) -> Result<()> {
    let result = execute_luau_result(args, bridge)?;
    println!("{}", serde_json::to_string_pretty(&result)?);
    Ok(())
}

fn validate_luau_syntax(code: &str) -> Result<()> {
    let parsed = full_moon::parse_fallible(code, full_moon::LuaVersion::luau());
    if let Some(error) = parsed.errors().first() {
        let (start, _) = error.range();
        bail!(
            "Invalid Luau syntax at {}:{}: {}",
            start.line(),
            start.character(),
            error.error_message()
        );
    }
    Ok(())
}

fn execute_luau_result(args: ExecuteLuauArgs, bridge: &BridgeServer) -> Result<Value> {
    let code = if let Some(code) = args.code {
        code
    } else if let Some(path) = args.file {
        fs::read_to_string(&path).with_context(|| format!("Failed to read {}", path.display()))?
    } else {
        bail!("Missing Luau code. Use -e <code> or -f <file>.");
    };
    validate_luau_syntax(&code)?;
    let client = args.client || args.player.is_some();
    let timeout = args.timeout.clamp(0.1, 20.0);
    let target = if client {
        BridgeTarget::Client
    } else {
        BridgeTarget::Main
    };
    if let Some(player) = args.player.as_deref() {
        wait_for_player_bridge(bridge, player, args.bridge_wait_seconds)?;
    }
    let result = bridge.call_for_selector(
        "executeLuau",
        json!({
            "code": code,
            "chunkName": "Renium",
            "context": if client { "client" } else { "plugin" },
            "timeoutSeconds": timeout,
        }),
        target,
        args.player.as_deref(),
    )?;
    ensure_luau_api_ok(&result)?;
    Ok(result)
}

fn studio_device_command(args: StudioDeviceArgs) -> Result<()> {
    if let Some(result) = try_daemon_control_request("device", studio_device_daemon_args(&args))? {
        println!("{}", serde_json::to_string_pretty(&result)?);
        return Ok(());
    }
    let ports = parse_bridge_ports(&args.bridge_ports)?;
    let (bridge, _listen_metrics) = BridgeServer::listen_with_initial_wait(
        &args.bridge_host,
        &ports,
        args.bridge_wait_seconds,
        false,
    )?;
    let required_channels = bridge.expected_channel_count();
    let ready_channels = bridge.wait_for_ready_channels_for_target(
        required_channels,
        Duration::from_secs_f64(args.bridge_wait_seconds.max(1.0)),
        BridgeTarget::Edit,
    );
    if ready_channels < required_channels {
        bail!(
            "Only {}/{} persistent edit plugin bridge channels are ready{}. Missing ports: {:?}",
            ready_channels,
            required_channels,
            place_filter()
                .map(|place| format!(" for place filter '{place}'"))
                .unwrap_or_default(),
            bridge.missing_ports_for_target(BridgeTarget::Edit)
        );
    }
    let bridge_info = bridge.cached_bridge_info_for_target(BridgeTarget::Edit)?;
    validate_bridge_info(&bridge_info)?;
    let result = studio_device_result(&args, &bridge)?;
    println!("{}", serde_json::to_string_pretty(&result)?);
    Ok(())
}

fn studio_device_resolution(raw: &str) -> Result<(u32, u32)> {
    let normalized = raw.trim().to_ascii_lowercase().replace('×', "x");
    let (width, height) = normalized
        .split_once('x')
        .with_context(|| format!("Invalid resolution '{raw}'. Use WIDTHxHEIGHT."))?;
    let width = width
        .trim()
        .parse::<u32>()
        .with_context(|| format!("Invalid resolution width in '{raw}'"))?;
    let height = height
        .trim()
        .parse::<u32>()
        .with_context(|| format!("Invalid resolution height in '{raw}'"))?;
    if width == 0 || height == 0 || width > i32::MAX as u32 || height > i32::MAX as u32 {
        bail!("Resolution must use positive 32-bit dimensions");
    }
    Ok((width, height))
}

fn studio_device_result(args: &StudioDeviceArgs, bridge: &BridgeServer) -> Result<Value> {
    let mut params = Map::new();
    params.insert("action".to_string(), Value::String(args.action.clone()));
    if let Some(device) = args.device.as_ref() {
        params.insert("device".to_string(), Value::String(device.clone()));
    }
    if let Some(orientation) = args.orientation.as_ref() {
        params.insert(
            "orientation".to_string(),
            Value::String(orientation.clone()),
        );
    }
    if let Some(scaling_mode) = args.scaling_mode.as_ref() {
        params.insert(
            "scalingMode".to_string(),
            Value::String(scaling_mode.clone()),
        );
    }
    if let Some(resolution) = args.resolution.as_deref() {
        let (width, height) = studio_device_resolution(resolution)?;
        params.insert("width".to_string(), json!(width));
        params.insert("height".to_string(), json!(height));
    }
    if let Some(pixel_density) = args.pixel_density {
        if !pixel_density.is_finite() || pixel_density <= 0.0 {
            bail!("Pixel density must be a finite number greater than zero");
        }
        params.insert("pixelDensity".to_string(), json!(pixel_density));
    }
    let result =
        bridge.call_for_target("deviceSimulator", Value::Object(params), BridgeTarget::Edit)?;
    ensure_plugin_api_ok(&result)?;
    Ok(result)
}

fn wait_for_player_bridge(bridge: &BridgeServer, player: &str, wait_seconds: f64) -> Result<()> {
    if bridge.wait_for_ready_player(player, Duration::from_secs_f64(wait_seconds.max(1.0))) {
        return Ok(());
    }
    bail!(
        "No connected play client matches player selector '{player}'. Connected bridges: {}",
        serde_json::to_string(&bridge.list_bridge_clients())?
    )
}

