const GITHUB_REPO: &str = "Superwheat/renium";
const PLUGIN_ASSET_NAME: &str = "Renium.rbxm";

fn roblox_plugins_dir() -> Result<PathBuf> {
    #[cfg(windows)]
    {
        let local = std::env::var("LOCALAPPDATA")
            .context("LOCALAPPDATA is not set; cannot locate the Roblox Plugins folder")?;
        Ok(PathBuf::from(local).join("Roblox").join("Plugins"))
    }
    #[cfg(target_os = "macos")]
    {
        let home = std::env::var("HOME")
            .context("HOME is not set; cannot locate the Roblox Plugins folder")?;
        Ok(PathBuf::from(home)
            .join("Documents")
            .join("Roblox")
            .join("Plugins"))
    }
    #[cfg(not(any(windows, target_os = "macos")))]
    {
        bail!("Roblox Studio is only available on Windows and macOS; pass --dir explicitly")
    }
}

fn renium_plugin_source(bytes: &[u8]) -> Result<String> {
    let dom = if bytes.starts_with(b"<roblox!") {
        rbx_binary::from_reader(bytes)
            .context("The plugin file is not a valid binary Roblox model")?
    } else {
        rbx_xml::from_reader_default(bytes)
            .context("The plugin file is not a valid XML Roblox model")?
    };
    let runtime = dom
        .descendants()
        .find(|instance| {
            instance.name == "BridgePluginRuntime" && instance.class.as_str() == "ModuleScript"
        })
        .context("The plugin file is not a Renium Studio plugin")?;
    let source = runtime
        .properties
        .iter()
        .find_map(|(name, value)| (name.as_str() == "Source").then_some(value))
        .and_then(rbx_variant_to_source_string)
        .context("The Renium Studio plugin runtime has no readable source")?;
    if !source.contains("BRIDGE_VERSION") {
        bail!("The plugin file is not a Renium Studio plugin");
    }
    Ok(source)
}

fn renium_plugin_version(bytes: &[u8]) -> Result<String> {
    let source = renium_plugin_source(bytes)?;
    let marker = "local BRIDGE_VERSION = \"";
    let start = source
        .find(marker)
        .map(|index| index + marker.len())
        .context("The Renium Studio plugin has no readable version")?;
    let rest = &source[start..];
    let end = rest
        .find('"')
        .context("The Renium Studio plugin version is malformed")?;
    let version = &rest[..end];
    if version.is_empty() {
        bail!("The Renium Studio plugin version is empty");
    }
    Ok(version.to_string())
}

pub(crate) fn validate_rbxm(bytes: &[u8]) -> Result<()> {
    validate_rbxm_version(bytes, BUILD_VERSION)
}

pub(crate) fn validate_rbxm_version(bytes: &[u8], expected: &str) -> Result<()> {
    let version = renium_plugin_version(bytes)?;
    if version != expected {
        bail!("The Studio plugin version {version} does not match Renium {expected}");
    }
    Ok(())
}

fn plugin_release_url(version: &str) -> String {
    format!("https://github.com/{GITHUB_REPO}/releases/download/v{version}/{PLUGIN_ASSET_NAME}")
}

fn download_compatible_plugin(destination: &Path) -> Result<String> {
    let url = plugin_release_url(BUILD_VERSION);
    let status = std::process::Command::new("curl")
        .args(["-fsSL", "--retry", "2", "--connect-timeout", "15", "-o"])
        .arg(destination)
        .arg(&url)
        .status()
        .context("Failed to run curl (it ships with Windows 10+ and macOS)")?;
    if !status.success() {
        bail!(
            "Downloading {url} failed ({status}); check your network or pass --file with a \
             local {PLUGIN_ASSET_NAME}"
        );
    }
    Ok(url)
}

fn setup_command(args: SetupArgs) -> Result<()> {
    let selected_actions =
        usize::from(args.status) + usize::from(args.repair) + usize::from(args.uninstall);
    if selected_actions > 1 {
        bail!("Use only one of --status, --repair, or --uninstall");
    }
    let plugins_dir = match args.dir.as_ref() {
        Some(dir) => PathBuf::from(dir),
        None => roblox_plugins_dir()?,
    };
    let target = plugins_dir.join(PLUGIN_ASSET_NAME);

    let exe_sibling = std::env::current_exe()
        .ok()
        .and_then(|exe| exe.parent().map(|dir| dir.join(PLUGIN_ASSET_NAME)))
        .filter(|path| path.is_file());
    if args.status {
        let installed = target.is_file();
        let installed_bytes = installed.then(|| fs::read(&target)).transpose()?;
        let installed_hash = installed_bytes.as_deref().map(sha256_hex);
        let installed_version = installed_bytes
            .as_deref()
            .and_then(|bytes| renium_plugin_version(bytes).ok());
        let identified = installed_version.is_some();
        let compatible = installed_version.as_deref() == Some(BUILD_VERSION);
        let bundled_hash = exe_sibling
            .as_deref()
            .map(fs::read)
            .transpose()?
            .map(|bytes| sha256_hex(&bytes));
        let response = json!({
            "ok": installed && compatible,
            "action": "status",
            "installed": installed,
            "identified": identified,
            "compatible": compatible,
            "installedAt": target,
            "installedVersion": installed_version,
            "installedSha256": installed_hash,
            "bundledSha256": bundled_hash,
            "matchesBundled": installed_hash.is_some() && installed_hash == bundled_hash,
            "version": BUILD_VERSION,
        });
        let text = if !installed {
            format!(
                "The Renium Studio plugin is not installed at {}",
                target.display()
            )
        } else if !compatible {
            match installed_version {
                Some(version) => format!(
                    "Renium Studio plugin {version} is installed at {} and does not match {BUILD_VERSION}",
                    target.display()
                ),
                None => format!(
                    "The file at {} is not an identifiable Renium Studio plugin",
                    target.display()
                ),
            }
        } else {
            format!(
                "Renium Studio plugin {} is installed at {}",
                BUILD_VERSION,
                target.display()
            )
        };
        return emit_global_output(&response, &text);
    }
    if args.uninstall {
        let _lifecycle_lock = (!args.dry_run)
            .then(lifecycle::acquire_lifecycle_lock)
            .transpose()?;
        let installed_bytes = target.is_file().then(|| fs::read(&target)).transpose()?;
        let installed_version = installed_bytes
            .as_deref()
            .map(renium_plugin_version)
            .transpose()
            .with_context(|| {
                format!(
                    "Refusing to remove {} because it is not an identifiable Renium Studio plugin",
                    target.display()
                )
            })?;
        if args.dry_run {
            #[cfg(target_os = "macos")]
            let managed_studio = studio_native_serializer::managed_studio_path()?;
            let response = json!({
                "ok": true,
                "action": "uninstall",
                "dryRun": true,
                "wouldRemove": target,
                "installed": target.is_file(),
                "installedVersion": installed_version,
            });
            #[cfg(target_os = "macos")]
            let response = {
                let mut response = response;
                response.as_object_mut().unwrap().insert(
                    "wouldRemoveManagedStudio".to_string(),
                    json!(managed_studio),
                );
                response
            };
            return emit_global_output(
                &response,
                &format!("Would remove the Studio plugin at {}", target.display()),
            );
        }
        #[cfg(target_os = "macos")]
        let managed_removal = studio_native_serializer::begin_managed_studio_removal()?;
        if target.is_file()
            && let Err(error) = fs::remove_file(&target)
        {
            #[cfg(target_os = "macos")]
            if let Err(rollback_error) = managed_removal.rollback() {
                return Err(error).context(format!(
                    "Failed to remove {} and managed Studio rollback failed: {rollback_error:#}",
                    target.display()
                ));
            }
            return Err(error).with_context(|| format!("Failed to remove {}", target.display()));
        }
        #[cfg(target_os = "macos")]
        managed_removal.commit()?;
        let response = json!({
            "ok": true,
            "action": "uninstall",
            "removed": target,
            "removedVersion": installed_version,
        });
        return emit_global_output(
            &response,
            &format!("Removed the Studio plugin from {}", target.display()),
        );
    }
    let staging_download =
        std::env::temp_dir().join(format!("renium-plugin-{}.rbxm", std::process::id()));

    let (source_path, source_label) = if let Some(file) = args.file.as_ref() {
        let path = PathBuf::from(file);
        if !path.is_file() {
            bail!("--file {} does not exist", path.display());
        }
        (path, format!("file {file}"))
    } else if let Some(sibling) = exe_sibling {
        let label = format!("bundled {}", sibling.display());
        (sibling, label)
    } else {
        let url = download_compatible_plugin(&staging_download)?;
        (staging_download.clone(), url)
    };

    let bytes = std::fs::read(&source_path)
        .with_context(|| format!("Failed to read {}", source_path.display()))?;
    validate_rbxm(&bytes)?;

    if args.dry_run {
        #[cfg(target_os = "macos")]
        let managed_studio = studio_native_serializer::setup_managed_studio(true)?;
        let _ = std::fs::remove_file(&staging_download);
        let response = json!({
            "ok": true,
            "action": "setup",
            "dryRun": true,
            "source": source_label,
            "wouldInstallTo": target.display().to_string(),
            "bytes": bytes.len(),
        });
        #[cfg(target_os = "macos")]
        let response = {
            let mut response = response;
            response.as_object_mut().unwrap().insert(
                "wouldPrepareStudioAt".to_string(),
                json!(managed_studio.display().to_string()),
            );
            response
        };
        return emit_global_output(
            &response,
            &format!(
                "Would install the Studio plugin from {source_label} to {}",
                target.display()
            ),
        );
    }

    let _lifecycle_lock = lifecycle::acquire_lifecycle_lock()?;
    std::fs::create_dir_all(&plugins_dir)
        .with_context(|| format!("Failed to create {}", plugins_dir.display()))?;
    #[cfg(target_os = "macos")]
    let previous_plugin = fs::read(&target).ok();
    lifecycle::install_bytes(&target, &bytes)?;
    let _ = std::fs::remove_file(&staging_download);

    #[cfg(target_os = "macos")]
    let managed_studio = match studio_native_serializer::setup_managed_studio(false) {
        Ok(path) => path,
        Err(error) => {
            let rollback = if let Some(previous) = previous_plugin.as_deref() {
                lifecycle::install_bytes(&target, previous)
            } else if target.is_file() {
                fs::remove_file(&target).map_err(anyhow::Error::from)
            } else {
                Ok(())
            };
            if let Err(rollback_error) = rollback {
                return Err(error).context(format!(
                    "Managed Studio setup failed and plugin rollback failed: {rollback_error:#}"
                ));
            }
            return Err(error);
        }
    };
    let response = json!({
        "ok": true,
        "action": if args.repair { "repair" } else { "setup" },
        "source": source_label,
        "installedTo": target.display().to_string(),
        "bytes": bytes.len(),
        "note": "Restart Roblox Studio (or toggle the plugin) to load the new version",
    });
    #[cfg(target_os = "macos")]
    let response = {
        let mut response = response;
        response.as_object_mut().unwrap().insert(
            "managedStudio".to_string(),
            json!(managed_studio.display().to_string()),
        );
        response.as_object_mut().unwrap().insert(
            "note".to_string(),
            json!("Open Renium Studio from Applications to use exact protected-property sync"),
        );
        response
    };
    emit_global_output(
        &response,
        &format!(
            "Installed the Studio plugin from {source_label} to {}",
            target.display()
        ),
    )
}

fn sha256_hex(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

fn list_clients_command(args: ListClientsArgs) -> Result<()> {
    if let Some(result) = try_daemon_control_request("clients", Vec::new())? {
        println!("{}", serde_json::to_string(&compact_json(result))?);
        return Ok(());
    }
    let ports = parse_bridge_ports(&args.bridge_ports)?;
    let (bridge, _listen_metrics) =
        BridgeServer::listen(&args.bridge_host, &ports, args.bridge_wait_seconds)?;
    println!(
        "{}",
        serde_json::to_string_pretty(&json!({ "clients": bridge.list_bridge_clients() }))?
    );
    Ok(())
}

fn editor_review_decision_daemon_args(args: &EditorReviewDecisionArgs) -> Vec<String> {
    let mut out = vec![
        args.decision.clone(),
        "-w".to_string(),
        args.bridge_wait_seconds.to_string(),
        "-H".to_string(),
        args.bridge_host.clone(),
        "-P".to_string(),
        args.bridge_ports.clone(),
    ];
    if let Some(review_id) = &args.review_id {
        out.push("-i".to_string());
        out.push(review_id.clone());
    }
    out
}

fn editor_review_decision_result(
    args: &EditorReviewDecisionArgs,
    bridge: &BridgeServer,
) -> Result<Value> {
    let result = bridge.call(
        "setEditorPushReviewDecision",
        json!({
            "reviewId": args.review_id,
            "decision": args.decision,
        }),
    )?;
    if result.get("accepted").and_then(Value::as_bool) != Some(true) {
        let error = result
            .get("error")
            .and_then(Value::as_str)
            .unwrap_or("Studio has no matching review awaiting a decision");
        bail!("{error}");
    }
    Ok(result)
}

fn editor_review_decision_command(args: EditorReviewDecisionArgs) -> Result<()> {
    let daemon_args = editor_review_decision_daemon_args(&args);
    let result = try_daemon_control_request("review", daemon_args)?
        .context("No Renium daemon is running; start `rbx bd` first")?;
    println!("{}", serde_json::to_string_pretty(&result)?);
    Ok(())
}

fn stop_studio_play_with_bridge_result(bridge: &BridgeServer) -> Result<Value> {
    let edit_pin = bridge.runtime_pin_for_selector(BridgeTarget::Edit, None)?;
    let edit_runtime_id = edit_pin.runtime_id.context(
        "Studio play control requires the current Renium plugin with runtime identity support",
    )?;
    let initial = studio_play_status_for_runtime(bridge, &edit_runtime_id)?;
    if studio_status_indicates_stopped(&initial)
        && initial.get("starting").and_then(Value::as_bool) != Some(true)
    {
        return Ok(initial);
    }
    let launch_nonce = initial
        .get("launchNonce")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let mut last_status = Value::Null;
    let mut last_play_roles = 0;
    for attempt in 1..=3 {
        let mut params = Map::new();
        params.insert("stop".to_string(), Value::Bool(true));
        if let Some(launch_nonce) = launch_nonce.as_ref() {
            params.insert(
                "launchNonce".to_string(),
                Value::String(launch_nonce.clone()),
            );
        }
        let stop_result = bridge.call_for_runtime_with_timeout(
            "startStopPlay",
            Value::Object(params),
            BridgeTarget::Edit,
            &edit_runtime_id,
            None,
        )?;
        ensure_plugin_api_ok(&stop_result)?;
        let deadline = Instant::now() + Duration::from_secs(3);
        let mut status_stopped = false;
        while Instant::now() < deadline {
            match studio_play_status_for_runtime(bridge, &edit_runtime_id) {
                Ok(status) => {
                    last_status = status.clone();
                    status_stopped = studio_status_indicates_stopped(&status);
                }
                Err(err) => {
                    last_status = json!({ "error": format!("{:#}", err) });
                    status_stopped = false;
                }
            }
            if status_stopped {
                break;
            }
            thread::sleep(Duration::from_millis(100));
        }
        if status_stopped {
            let teardown_deadline = Instant::now() + Duration::from_secs(10);
            loop {
                let (clients, play_roles) = if let Some(launch_nonce) = launch_nonce.as_ref() {
                    let launch = TestLaunch {
                        nonce: launch_nonce.clone(),
                        edit_runtime_id: edit_runtime_id.clone(),
                    };
                    let clients = test_launch_clients(bridge, &launch);
                    let count = clients.len();
                    (clients, count)
                } else {
                    (Vec::new(), 0)
                };
                last_play_roles = play_roles;
                if play_roles == 0 {
                    return Ok(json!({
                        "ok": true,
                        "action": "stop",
                        "method": "pluginApi",
                        "attempts": attempt,
                        "stopResult": stop_result,
                        "status": last_status,
                        "clients": clients,
                    }));
                }
                if Instant::now() >= teardown_deadline {
                    break;
                }
                thread::sleep(Duration::from_millis(250));
            }
        }
    }
    if last_play_roles > 0 {
        bail!(
            "Studio reported edit mode but {} play bridge(s) are still connected after stop; last status: {}, connected bridges: {}",
            last_play_roles,
            serde_json::to_string(&last_status)?,
            serde_json::to_string(&bridge.list_bridge_clients())?
        );
    }
    bail!(
        "Studio did not report edit mode after plugin stop request; last status: {}",
        serde_json::to_string(&last_status)?
    )
}

fn studio_play_status_for_runtime(bridge: &BridgeServer, runtime_id: &str) -> Result<Value> {
    let status = bridge.call_for_runtime_with_timeout(
        "startStopPlay",
        json!({}),
        BridgeTarget::Edit,
        runtime_id,
        None,
    )?;
    ensure_plugin_api_ok(&status)?;
    Ok(status)
}

fn studio_status_indicates_stopped(status: &Value) -> bool {
    if let Some(running) = status.get("running").and_then(Value::as_bool) {
        return !running;
    }
    status
        .get("studioTest")
        .and_then(|value| value.get("editModeActive"))
        .and_then(Value::as_bool)
        == Some(true)
}

fn test_command(args: TestArgs) -> Result<()> {
    if !matches!(args.mode.as_str(), "play" | "run" | "server") {
        bail!(
            "Invalid test mode '{}'; use play, run, or server",
            args.mode
        );
    }
    if args.players.is_some() && args.mode != "play" {
        bail!("--players can only be used with --mode play");
    }
    let mut daemon_args = vec![
        "--mode".to_string(),
        args.mode,
        "--timeout".to_string(),
        args.timeout.to_string(),
    ];
    if let Some(players) = args.players {
        daemon_args.push("--players".to_string());
        daemon_args.push(players.to_string());
    }
    if args.fail_on_error {
        daemon_args.push("--fail-on-error".to_string());
    }
    if let Some(player) = args.player {
        daemon_args.push("--player".to_string());
        daemon_args.push(player);
    }
    let result = try_daemon_control_request("test", daemon_args)?
        .context("No Renium daemon is running; start `rbx bd` first")?;
    println!("{}", serde_json::to_string_pretty(&result)?);
    if result.get("ok").and_then(Value::as_bool) == Some(false) {
        let count = result
            .get("errors")
            .and_then(Value::as_array)
            .map(Vec::len)
            .unwrap_or(0);
        bail!("Test console reported {count} error(s)");
    }
    Ok(())
}

#[derive(Default)]
struct TestConsoleCursor {
    epoch: Option<String>,
    seq: u64,
}

#[derive(Default)]
struct TestConsoleCapture {
    cursors: HashMap<String, TestConsoleCursor>,
    errors: Vec<String>,
    truncated: bool,
}

struct TestLaunch {
    nonce: String,
    edit_runtime_id: String,
}

fn ingest_test_console_payload(
    runtime_id: &str,
    label: &str,
    capture: &mut TestConsoleCapture,
    console: &Value,
    restart_on_epoch_change: bool,
) -> bool {
    capture.truncated |= console.get("truncated").and_then(Value::as_bool) == Some(true);
    let next_epoch = console
        .get("epoch")
        .and_then(Value::as_str)
        .map(str::to_string);
    let previous_epoch = capture
        .cursors
        .get(runtime_id)
        .and_then(|cursor| cursor.epoch.clone());
    if previous_epoch.is_some() && previous_epoch != next_epoch {
        let cursor = capture.cursors.entry(runtime_id.to_string()).or_default();
        cursor.epoch = next_epoch.clone();
        cursor.seq = 0;
        if restart_on_epoch_change {
            return true;
        }
    }
    let previous_seq = capture
        .cursors
        .get(runtime_id)
        .map(|cursor| cursor.seq)
        .unwrap_or(0);
    let mut highest_seq = previous_seq;
    if let Some(entries) = console.get("entries").and_then(Value::as_array) {
        for entry in entries {
            let entry_seq = entry.get("seq").and_then(Value::as_u64);
            if entry_seq.is_some_and(|seq| seq <= previous_seq) {
                continue;
            }
            if let Some(seq) = entry_seq {
                highest_seq = highest_seq.max(seq);
            }
            let level = entry
                .get("type")
                .or_else(|| entry.get("level"))
                .and_then(Value::as_str)
                .unwrap_or("output");
            let message = entry
                .get("message")
                .and_then(Value::as_str)
                .unwrap_or_default();
            println!("[{label} {level}] {message}");
            if matches!(
                level.to_ascii_lowercase().as_str(),
                "error" | "messageerror"
            ) {
                capture.errors.push(format!("{label}: {message}"));
            }
        }
    }
    highest_seq = highest_seq.max(
        console
            .get("nextSeq")
            .and_then(Value::as_u64)
            .unwrap_or(highest_seq),
    );
    let cursor = capture.cursors.entry(runtime_id.to_string()).or_default();
    cursor.epoch = next_epoch;
    cursor.seq = highest_seq;
    false
}

fn test_launch_clients(bridge: &BridgeServer, launch: &TestLaunch) -> Vec<Value> {
    bridge
        .list_bridge_clients()
        .into_iter()
        .filter(|entry| {
            entry.get("launchNonce").and_then(Value::as_str) == Some(launch.nonce.as_str())
                && entry.get("launchEditRuntimeId").and_then(Value::as_str)
                    == Some(launch.edit_runtime_id.as_str())
                && (entry["role"] == BRIDGE_ROLE_PLAY_SERVER
                    || entry["role"] == BRIDGE_ROLE_PLAY_CLIENT)
        })
        .collect()
}

fn drain_test_console(
    bridge: &BridgeServer,
    target: BridgeTarget,
    runtime_id: &str,
    label: &str,
    capture: &mut TestConsoleCapture,
    deadline: Instant,
) -> Result<()> {
    loop {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Ok(());
        }
        let cursor_seq = capture
            .cursors
            .get(runtime_id)
            .map(|cursor| cursor.seq)
            .unwrap_or(0);
        let console = bridge.call_for_runtime_with_timeout(
            "getConsoleOutput",
            json!({
                "limit": 200,
                "sinceSeq": cursor_seq,
                "fromOldest": cursor_seq == 0,
                "clear": false,
            }),
            target,
            runtime_id,
            Some(remaining.min(BRIDGE_DEFAULT_RESPONSE_TIMEOUT)),
        )?;
        ensure_plugin_api_ok(&console)?;
        if ingest_test_console_payload(runtime_id, label, capture, &console, true) {
            continue;
        }
        if console.get("hasMore").and_then(Value::as_bool) != Some(true) {
            return Ok(());
        }
        let next_seq = capture
            .cursors
            .get(runtime_id)
            .map(|cursor| cursor.seq)
            .unwrap_or(0);
        if next_seq <= cursor_seq {
            bail!("Studio console page cursor did not advance");
        }
    }
}

fn test_client_matches_selector(entry: &Value, selector: &str) -> bool {
    if entry["role"] != BRIDGE_ROLE_PLAY_CLIENT {
        return false;
    }
    let name = entry
        .get("playerName")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if name.eq_ignore_ascii_case(selector) {
        return true;
    }
    selector.parse::<i64>().ok().is_some_and(|index| {
        name.eq_ignore_ascii_case(&format!("Player{index}"))
            || entry.get("playerUserId").and_then(Value::as_i64) == Some(-index)
    })
}

fn drain_test_consoles(
    bridge: &BridgeServer,
    launch: &TestLaunch,
    capture: &mut TestConsoleCapture,
    deadline: Instant,
) -> Result<Vec<Value>> {
    let clients = test_launch_clients(bridge, launch);
    for entry in &clients {
        let Some(runtime_id) = entry.get("runtimeId").and_then(Value::as_str) else {
            bail!("A launched Studio bridge has no runtime identity");
        };
        let role = entry
            .get("role")
            .and_then(Value::as_str)
            .unwrap_or_default();
        let target = if role == BRIDGE_ROLE_PLAY_CLIENT {
            BridgeTarget::Client
        } else {
            BridgeTarget::Main
        };
        let player = entry
            .get("playerName")
            .and_then(Value::as_str)
            .filter(|name| !name.is_empty());
        let label = player
            .map(|name| format!("{role}:{name}"))
            .unwrap_or_else(|| role.to_string());
        drain_test_console(bridge, target, runtime_id, &label, capture, deadline)?;
    }
    for final_snapshot in bridge.take_final_console_snapshots(launch) {
        let runtime_id = final_snapshot
            .get("runtimeId")
            .and_then(Value::as_str)
            .unwrap_or_default();
        let role = final_snapshot
            .get("role")
            .and_then(Value::as_str)
            .unwrap_or("play");
        let player = final_snapshot
            .get("playerName")
            .and_then(Value::as_str)
            .filter(|name| !name.is_empty());
        let label = player
            .map(|name| format!("{role}:{name}"))
            .unwrap_or_else(|| role.to_string());
        if let Some(snapshot) = final_snapshot.get("snapshot") {
            ingest_test_console_payload(runtime_id, &label, capture, snapshot, false);
        }
    }
    Ok(clients)
}

fn start_test_session_with_deadline(
    args: &TestArgs,
    bridge: &BridgeServer,
    launch: &TestLaunch,
    deadline: Instant,
    owned: &mut bool,
) -> Result<Value> {
    let remaining = deadline.saturating_duration_since(Instant::now());
    if remaining.is_zero() {
        bail!("Timed test expired before Studio could start");
    }
    let mode = if matches!(args.mode.as_str(), "run" | "server") {
        "run"
    } else {
        "play"
    };
    let start_result = bridge.call_for_runtime_with_timeout(
        "startStopPlay",
        json!({
            "start": true,
            "mode": mode,
            "players": args.players,
            "launchNonce": launch.nonce,
        }),
        BridgeTarget::Edit,
        &launch.edit_runtime_id,
        Some(remaining.min(BRIDGE_DEFAULT_RESPONSE_TIMEOUT)),
    );
    let start = match start_result {
        Ok(start) => start,
        Err(error) => {
            let probe_timeout = deadline
                .saturating_duration_since(Instant::now())
                .min(Duration::from_secs(1));
            if !probe_timeout.is_zero()
                && let Ok(status) = bridge.call_for_runtime_with_timeout(
                    "startStopPlay",
                    json!({}),
                    BridgeTarget::Edit,
                    &launch.edit_runtime_id,
                    Some(probe_timeout),
                )
                && status.get("launchNonce").and_then(Value::as_str) == Some(launch.nonce.as_str())
            {
                *owned = true;
            }
            return Err(error);
        }
    };
    if start.get("launchNonce").and_then(Value::as_str) == Some(launch.nonce.as_str()) {
        *owned = true;
    }
    ensure_plugin_api_ok(&start)?;
    if start.get("launchNonce").and_then(Value::as_str) != Some(launch.nonce.as_str()) {
        bail!("Studio started a different test session");
    }
    loop {
        let clients = test_launch_clients(bridge, launch);
        let server_ready = clients
            .iter()
            .any(|entry| entry["role"] == BRIDGE_ROLE_PLAY_SERVER);
        let player_count_ready = args.players.is_none_or(|players| {
            clients
                .iter()
                .filter(|entry| entry["role"] == BRIDGE_ROLE_PLAY_CLIENT)
                .count()
                >= players as usize
        });
        let selected_player_ready = args.player.as_deref().is_none_or(|selector| {
            clients
                .iter()
                .any(|entry| test_client_matches_selector(entry, selector))
        });
        let ready = server_ready && player_count_ready && selected_player_ready;
        if ready {
            return Ok(json!({
                "ok": true,
                "mode": args.mode,
                "players": args.players,
                "launchNonce": launch.nonce,
                "editRuntimeId": launch.edit_runtime_id,
                "startResult": start,
                "clients": clients,
            }));
        }
        if Instant::now() >= deadline {
            bail!("Timed test expired while waiting for Studio play mode");
        }
        thread::sleep(
            Duration::from_millis(100).min(deadline.saturating_duration_since(Instant::now())),
        );
    }
}

fn stop_test_session_with_deadline(
    bridge: &BridgeServer,
    launch: &TestLaunch,
    capture: &mut TestConsoleCapture,
    deadline: Instant,
) -> Result<Value> {
    let remaining = deadline.saturating_duration_since(Instant::now());
    if remaining.is_zero() {
        bail!("Timed test exhausted its teardown deadline");
    }
    let initial_drain_deadline = Instant::now()
        + deadline
            .saturating_duration_since(Instant::now())
            .min(Duration::from_secs(1));
    let mut drain_error =
        drain_test_consoles(bridge, launch, capture, initial_drain_deadline).err();
    let remaining = deadline.saturating_duration_since(Instant::now());
    if remaining.is_zero() {
        bail!("Timed test exhausted its teardown deadline before requesting stop");
    }
    let stop = bridge.call_for_runtime_with_timeout(
        "startStopPlay",
        json!({
            "stop": true,
            "launchNonce": launch.nonce,
            "waitForStopped": false,
        }),
        BridgeTarget::Edit,
        &launch.edit_runtime_id,
        Some(remaining.min(BRIDGE_DEFAULT_RESPONSE_TIMEOUT)),
    )?;
    ensure_plugin_api_ok(&stop)?;
    loop {
        let drain_deadline = Instant::now()
            + deadline
                .saturating_duration_since(Instant::now())
                .min(Duration::from_millis(750));
        if let Err(error) = drain_test_consoles(bridge, launch, capture, drain_deadline)
            && drain_error.is_none()
        {
            drain_error = Some(error);
        }
        if Instant::now() >= deadline {
            bail!("Studio test bridges did not stop before the teardown deadline");
        }
        let remaining = deadline.saturating_duration_since(Instant::now());
        let terminal = bridge.call_for_runtime_with_timeout(
            "startStopPlay",
            json!({}),
            BridgeTarget::Edit,
            &launch.edit_runtime_id,
            Some(remaining.min(BRIDGE_DEFAULT_RESPONSE_TIMEOUT)),
        )?;
        ensure_plugin_api_ok(&terminal)?;
        let clients = test_launch_clients(bridge, launch);
        let stopped = terminal.get("running").and_then(Value::as_bool) == Some(false)
            && terminal.get("starting").and_then(Value::as_bool) != Some(true);
        if stopped && clients.is_empty() {
            let final_drain_deadline = Instant::now()
                + deadline
                    .saturating_duration_since(Instant::now())
                    .min(Duration::from_secs(1));
            if let Err(error) = drain_test_consoles(bridge, launch, capture, final_drain_deadline)
                && drain_error.is_none()
            {
                drain_error = Some(error);
            }
            if let Some(error) = drain_error {
                return Err(error.context("Studio stopped, but final console collection failed"));
            }
            return Ok(json!({
                "ok": true,
                "action": "stop",
                "launchNonce": launch.nonce,
                "stopResult": stop,
                "terminalResult": terminal,
                "clients": clients,
            }));
        }
        thread::sleep(
            Duration::from_millis(100).min(deadline.saturating_duration_since(Instant::now())),
        );
    }
}

fn timed_test_result(args: TestArgs, bridge: &BridgeServer) -> Result<Value> {
    if !matches!(args.mode.as_str(), "play" | "run" | "server") {
        bail!(
            "Invalid test mode '{}'; use play, run, or server",
            args.mode
        );
    }
    if args.players.is_some() && args.mode != "play" {
        bail!("--players can only be used with --mode play");
    }
    if !args.timeout.is_finite() || args.timeout <= 0.0 {
        bail!("--timeout must be a finite number greater than zero");
    }
    let timeout = args.timeout.clamp(0.1, 60.0 * 60.0);
    let started = Instant::now();
    let run_deadline = started + Duration::from_secs_f64(timeout);
    let launch = new_play_launch(bridge, "test")?;
    let mut console = TestConsoleCapture::default();
    let mut owns_test = false;
    let start = match start_test_session_with_deadline(
        &args,
        bridge,
        &launch,
        run_deadline,
        &mut owns_test,
    ) {
        Ok(start) => start,
        Err(error) => {
            cancel_test_launch_best_effort(bridge, &launch);
            if !owns_test {
                return Err(
                    error.context("Timed test failed to start; exact launch cleanup was requested")
                );
            }
            let teardown_deadline = Instant::now() + Duration::from_secs(10);
            let cleanup =
                stop_test_session_with_deadline(bridge, &launch, &mut console, teardown_deadline);
            return match cleanup {
                Ok(_) => Err(error.context("Timed test failed to start; cleanup completed")),
                Err(cleanup_error) => Err(error.context(format!(
                    "Timed test failed to start and cleanup also failed: {cleanup_error:#}"
                ))),
            };
        }
    };
    let run_result = (|| -> Result<()> {
        while Instant::now() < run_deadline {
            drain_test_consoles(bridge, &launch, &mut console, run_deadline)?;
            thread::sleep(
                Duration::from_millis(250)
                    .min(run_deadline.saturating_duration_since(Instant::now())),
            );
        }
        Ok(())
    })();
    let teardown_deadline = Instant::now() + Duration::from_secs(10);
    let stop_result =
        stop_test_session_with_deadline(bridge, &launch, &mut console, teardown_deadline);
    if let Err(run_error) = run_result {
        return match stop_result {
            Ok(_) => Err(run_error),
            Err(stop_error) => Err(run_error.context(format!(
                "Timed test execution failed and teardown also failed: {stop_error:#}"
            ))),
        };
    }
    let stop = stop_result?;
    let terminal_error = stop
        .pointer("/terminalResult/lastError")
        .and_then(Value::as_str)
        .filter(|message| !message.is_empty())
        .map(str::to_string);
    if let Some(message) = terminal_error.as_ref() {
        console
            .errors
            .push(format!("Studio test service: {message}"));
    }
    if console.truncated {
        let message = "Studio console history was truncated during the timed test".to_string();
        if args.fail_on_error {
            console.errors.push(message);
        } else {
            log_global(2, format_args!("{message}"));
        }
    }
    Ok(json!({
        "ok": terminal_error.is_none() && (!args.fail_on_error || console.errors.is_empty()),
        "mode": args.mode,
        "players": args.players,
        "launchNonce": launch.nonce,
        "editRuntimeId": launch.edit_runtime_id,
        "elapsedSeconds": started.elapsed().as_secs_f64(),
        "errors": console.errors,
        "terminalError": terminal_error,
        "consoleTruncated": console.truncated,
        "start": start,
        "stop": stop,
    }))
}

fn structural_source_root(
    project: Option<&Path>,
    project_root: &Path,
    src_root: Option<&Path>,
) -> Result<PathBuf> {
    if let Some(project) = project {
        let loaded = project_config::load_project(Some(project), None)?;
        return Ok(loaded
            .root
            .join(src_root.unwrap_or(&loaded.project.source_root)));
    }
    let source_root = src_root.unwrap_or_else(|| Path::new("src"));
    let (project_root, source_root) = configured_project_layout(project_root, source_root)?;
    Ok(absolutize_under(&project_root, &source_root))
}

fn structural_project(
    project: Option<&Path>,
    project_root: &Path,
    src_root: Option<&Path>,
) -> Result<Option<project_config::LoadedProject>> {
    if src_root.is_some() {
        return Ok(None);
    }
    load_structural_project(project, project_root).map(Some)
}

fn load_structural_project(
    project: Option<&Path>,
    project_root: &Path,
) -> Result<project_config::LoadedProject> {
    if let Some(project) = project {
        return project_config::load_project(Some(project), None);
    }
    if let Some(loaded) = project_config::try_load_project(None, Some(project_root))? {
        return Ok(loaded);
    }
    let (root, source_root) = configured_project_layout(project_root, Path::new("src"))?;
    let project = project_config::ReniumProject {
        source_root,
        ..project_config::ReniumProject::default()
    };
    Ok(project_config::LoadedProject {
        path: root.join(project_config::PROJECT_FILE_NAME),
        root,
        project,
    })
}

fn projected_structural_target(
    stage: &project_config::ProjectionStage,
    service: &str,
    settings_id: Option<&str>,
) -> Result<(Vec<String>, Vec<usize>)> {
    let settings = existing_service_settings_path(&stage.root().join(service));
    if !settings.is_file() {
        bail!("Projected service '{service}' has no Renium store");
    }
    if settings_id.is_none() {
        return Ok((vec![service.to_string()], vec![1]));
    }
    let document = SettingsBytecode::read_file(&settings)?;
    let settings_id = settings_id.unwrap_or_default();
    let index = document
        .instances
        .iter()
        .position(|instance| instance.settings_id == settings_id)
        .with_context(|| {
            format!("Projected service '{service}' has no instance id '{settings_id}'")
        })?;
    let paths = build_editor_instance_paths(&document, service);
    let path = paths
        .get(index)
        .and_then(Option::as_ref)
        .with_context(|| format!("Cannot resolve the projected path for '{settings_id}'"))?;
    Ok((path.path_segments.clone(), path.path_ordinals.clone()))
}

fn projected_structural_store(
    loaded: &project_config::LoadedProject,
    stage: &project_config::ProjectionStage,
    service: &str,
    settings_id: Option<&str>,
    reject_declarative_target: bool,
    override_packages: bool,
) -> Result<(PathBuf, Vec<String>, Option<String>)> {
    let (target, target_ordinals) = projected_structural_target(stage, service, settings_id)?;
    build_loaded_project_link_enforcement(loaded, override_packages)?
        .reject_read_only_package_path(service, &target, &target_ordinals)?;
    if settings_id.is_none() && target_ordinals.iter().any(|ordinal| *ordinal > 1) {
        bail!(
            "Projected path '{}' selects a duplicate sibling that cannot map to one filesystem owner",
            target.join(".")
        );
    }
    if stage.target_is_transformed(&target) {
        bail!(
            "Projected path '{}' is generated by a sync rule; edit its source file instead",
            target.join(".")
        );
    }
    if reject_declarative_target && project_config::project_target_is_declarative(loaded, &target)?
    {
        bail!(
            "Projected path '{}' is named by project configuration; edit the project or metadata sidecar instead",
            target.join(".")
        );
    }
    let store = project_config::project_structural_store(loaded, &target)?;
    let canonical_id = settings_id
        .map(|settings_id| {
            if let Some((source, canonical_id)) = stage.canonical_identity(settings_id) {
                if path_key(source) != path_key(&store) {
                    bail!(
                        "Projected instance '{}' resolves to a different canonical store",
                        target.join(".")
                    );
                }
                Ok(canonical_id.to_string())
            } else {
                let document = SettingsBytecode::read_file(&store)?;
                if document
                    .instances
                    .iter()
                    .any(|instance| instance.settings_id == settings_id)
                {
                    Ok(settings_id.to_string())
                } else {
                    bail!(
                        "Projected instance '{}' exists only in project configuration and is not structurally writable",
                        target.join(".")
                    )
                }
            }
        })
        .transpose()?;
    Ok((store, target, canonical_id))
}

fn create_instance_command(args: CreateInstanceArgs, project: Option<&Path>) -> Result<()> {
    let loaded_project = structural_project(project, &args.project_root, args.src_root.as_deref())?;
    let settings_file = if let Some(loaded) = loaded_project.as_ref() {
        let stage = project_config::stage_project(loaded)?;
        let (settings_file, _, parent_settings_id) = projected_structural_store(
            loaded,
            &stage,
            &args.service,
            args.parent_settings_id.as_deref(),
            false,
            args.override_packages,
        )?;
        return bytecode_add_instance(BytecodeAddInstanceArgs {
            service_or_file: None,
            settings_file: Some(settings_file),
            name: args.name,
            class_name: args.class_name,
            settings_id: None,
            parent_index: None,
            parent_settings_id,
            parent_name: None,
            parent_class_name: None,
            no_parent: false,
            properties: args.properties,
            attributes: args.attributes,
            pretty: true,
        });
    } else {
        let src_root =
            structural_source_root(project, &args.project_root, args.src_root.as_deref())?;
        existing_service_settings_path(&src_root.join(&args.service))
    };
    if !settings_file.is_file() {
        bail!(
            "Service '{}' has no Renium store at {}",
            args.service,
            settings_file.display()
        );
    }
    bytecode_add_instance(BytecodeAddInstanceArgs {
        service_or_file: None,
        settings_file: Some(settings_file),
        name: args.name,
        class_name: args.class_name,
        settings_id: None,
        parent_index: None,
        parent_settings_id: args.parent_settings_id,
        parent_name: None,
        parent_class_name: None,
        no_parent: false,
        properties: args.properties,
        attributes: args.attributes,
        pretty: true,
    })
}

fn clone_instance_command(args: CloneInstanceCommandArgs, project: Option<&Path>) -> Result<()> {
    let loaded = load_structural_project(project, &args.project_root)?;
    let stage = project_config::stage_project(&loaded)?;
    let (source_file, source_target, source_id) = projected_structural_store(
        &loaded,
        &stage,
        &args.service,
        Some(&args.settings_id),
        true,
        args.override_packages,
    )?;
    let (parent_file, parent_target, parent_id) = projected_structural_store(
        &loaded,
        &stage,
        &args.service,
        Some(&args.parent_settings_id),
        false,
        args.override_packages,
    )?;
    if source_file != parent_file {
        bail!(
            "Copying '{}' to '{}' crosses projected owners",
            source_target.join("."),
            parent_target.join(".")
        );
    }
    bytecode_clone_instance(BytecodeCloneInstanceArgs {
        service_or_file: None,
        settings_file: Some(source_file),
        service: args.service,
        settings_id: source_id,
        index: None,
        name: None,
        class_name: None,
        parent_index: None,
        parent_settings_id: parent_id,
        parent_name: None,
        parent_class_name: None,
        pretty: true,
    })
}

fn move_instance_command(args: MoveInstanceArgs, project: Option<&Path>) -> Result<()> {
    let target_service = args
        .target_service
        .clone()
        .unwrap_or_else(|| args.service.clone());
    let loaded_project = structural_project(project, &args.project_root, args.src_root.as_deref())?;
    let (source_file, target_file) = if let Some(loaded) = loaded_project.as_ref() {
        let stage = project_config::stage_project(loaded)?;
        let (source_file, source_target, source_id) = projected_structural_store(
            loaded,
            &stage,
            &args.service,
            Some(&args.settings_id),
            true,
            args.override_packages,
        )?;
        let (target_file, target_parent, parent_id) = projected_structural_store(
            loaded,
            &stage,
            &target_service,
            Some(&args.parent_settings_id),
            false,
            args.override_packages,
        )?;
        if source_file != target_file {
            bail!(
                "Moving '{}' to '{}' crosses projected owners; move the canonical files instead",
                source_target.join("."),
                target_parent.join(".")
            );
        }
        return bytecode_set_property(BytecodeSetPropertyArgs {
            service_or_file: None,
            settings_file: Some(source_file),
            settings_id: source_id,
            index: None,
            name: None,
            class_name: None,
            path_segments_json: None,
            path_ordinals_json: "[]".to_string(),
            property: "Parent".to_string(),
            value_json: None,
            value_str: parent_id,
            value_num: None,
            value_bool: None,
            value_null: false,
            scope: "metadata".to_string(),
            pretty: true,
        });
    } else {
        let src_root =
            structural_source_root(project, &args.project_root, args.src_root.as_deref())?;
        (
            existing_service_settings_path(&src_root.join(&args.service)),
            existing_service_settings_path(&src_root.join(&target_service)),
        )
    };
    if !source_file.is_file() {
        bail!("Source service '{}' has no Renium store", args.service);
    }
    if target_service == args.service {
        return bytecode_set_property(BytecodeSetPropertyArgs {
            service_or_file: None,
            settings_file: Some(source_file),
            settings_id: Some(args.settings_id),
            index: None,
            name: None,
            class_name: None,
            path_segments_json: None,
            path_ordinals_json: "[]".to_string(),
            property: "Parent".to_string(),
            value_json: None,
            value_str: Some(args.parent_settings_id),
            value_num: None,
            value_bool: None,
            value_null: false,
            scope: "metadata".to_string(),
            pretty: true,
        });
    }
    if !target_file.is_file() {
        bail!("Target service '{target_service}' has no Renium store");
    }
    bail!("Cross-service moves are unavailable because Studio cannot apply them atomically")
}

