        let names = ["Foo", "foo", "foo_2", "Foo"];
        let stems = names
            .iter()
            .map(|name| unique_child_stem(name, &mut used, &mut suffixes))
            .collect::<Vec<_>>();

        assert_eq!(stems, vec!["Foo", "foo_2", "foo_2_2", "Foo_3"]);
