    fn assert_rbx_vector3_close(
        value: RbxVector3,
        expected_x: f32,
        expected_y: f32,
        expected_z: f32,
    ) {
        let epsilon = 0.0001_f32;
        assert!(
            (value.x - expected_x).abs() <= epsilon,
            "x: {} != {}",
            value.x,
            expected_x
        );
        assert!(
            (value.y - expected_y).abs() <= epsilon,
            "y: {} != {}",
            value.y,
            expected_y
        );
        assert!(
            (value.z - expected_z).abs() <= epsilon,
            "z: {} != {}",
            value.z,
            expected_z
        );
    }

    fn assert_rbx_color3_close(
        value: RbxColor3,
        expected_r: f32,
        expected_g: f32,
        expected_b: f32,
    ) {
        let epsilon = 0.0001_f32;
        assert!(
            (value.r - expected_r).abs() <= epsilon,
            "r: {} != {}",
            value.r,
            expected_r
        );
        assert!(
            (value.g - expected_g).abs() <= epsilon,
            "g: {} != {}",
            value.g,
            expected_g
        );
        assert!(
            (value.b - expected_b).abs() <= epsilon,
            "b: {} != {}",
            value.b,
            expected_b
        );
    }

