    fn link_test_dir(tag: &str) -> PathBuf {
        static COUNTER: AtomicU64 = AtomicU64::new(0);
        let n = COUNTER.fetch_add(1, Ordering::SeqCst);
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let dir = std::env::temp_dir().join(format!("renium-link-test-{tag}-{nanos}-{n}"));
        fs::create_dir_all(&dir).unwrap();
        dir
    }

    #[test]
    fn link_manifest_parses_source_variants() {
        let raw = r#"{
            "version": 1,
            "links": [
                {"id":"a","source":{"type":"local","path":"links/Logger.luau"},
                 "targets":[{"service":"ReplicatedStorage","path":["ReplicatedStorage","Logger"]}]},
                {"id":"b","source":{"type":"git","url":"https://example.com/r.git","ref":"main","subpath":"src"},
                 "targets":[{"service":"ServerScriptService","path":["ServerScriptService","R"]}]},
                {"id":"c","readOnly":false,"source":{"type":"wally","package":"evaera/promise","version":"^4.0.0"},
                 "targets":[]}
            ],
            "broken":[{"service":"ServerScriptService","path":["ServerScriptService","R"]}]
        }"#;
        let manifest: LinkManifest = serde_json::from_str(raw).unwrap();
        assert_eq!(manifest.links.len(), 3);
        assert!(manifest.links[0].read_only, "readOnly defaults to true");
        assert!(!manifest.links[2].read_only);
        match &manifest.links[1].source {
            LinkSource::Git {
                url,
                git_ref,
                subpath,
            } => {
                assert_eq!(url, "https://example.com/r.git");
                assert_eq!(git_ref.as_deref(), Some("main"));
                assert_eq!(subpath.as_deref(), Some("src"));
            }
            other => panic!("expected git source, got {other:?}"),
        }
        assert_eq!(manifest.links[2].source.kind(), "wally");
        assert_eq!(manifest.broken.len(), 1);
    }

    #[test]
    fn link_target_segments_strips_service_prefix() {
        let with_prefix = LinkTargetRef {
            service: "ReplicatedStorage".into(),
            path: vec!["ReplicatedStorage".into(), "A".into(), "B".into()],
            ords: vec![],
        };
        assert_eq!(
            link_target_segments(&with_prefix),
            vec!["A".to_string(), "B".to_string()]
        );
        let without = LinkTargetRef {
            service: "ReplicatedStorage".into(),
            path: vec!["A".into(), "B".into()],
            ords: vec![],
        };
        assert_eq!(
            link_target_segments(&without),
            vec!["A".to_string(), "B".to_string()]
        );
    }

    #[test]
    fn link_add_unbreaks_matching_target() {
        let dir = link_test_dir("link-add-unbreaks");
        let manifest_path = dir.join("renium-link.json");
        fs::write(
            &manifest_path,
            r#"{
                "version":1,
                "links":[{
                    "id":"pkg",
                    "source":{"type":"local","path":"links/pkg.rbsync"},
                    "targets":[{"service":"ReplicatedStorage","path":["ReplicatedStorage","Pkg"]}]
                }],
                "broken":[{"service":"ReplicatedStorage","path":["ReplicatedStorage","Pkg"]}]
            }"#,
        )
        .unwrap();

        link_add(LinkAddArgs {
            project_root: dir.clone(),
            manifest: PathBuf::from("renium-link.json"),
            id: Some("pkg".into()),
            source_type: "local".into(),
            source: None,
            source_ref: None,
            source_subpath: None,
            service: "ReplicatedStorage".into(),
            path_segments_json: r#"["ReplicatedStorage","Pkg"]"#.into(),
            path_ordinals_json: "[]".into(),
            writable: false,
            pretty: false,
        })
        .unwrap();

        let manifest = read_link_manifest(&manifest_path).unwrap();
        assert_eq!(manifest.links[0].targets.len(), 1);
        assert!(manifest.broken.is_empty());
        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn link_add_rejects_target_owned_by_another_link() {
        let dir = link_test_dir("link-add-target-collision");
        let manifest_path = dir.join("renium-link.json");
        write_link_manifest(
            &manifest_path,
            &LinkManifest {
                version: LINK_MANIFEST_VERSION,
                cache_dir: None,
                links: vec![LinkEntry {
                    id: "country-a".into(),
                    read_only: true,
                    source: LinkSource::Local {
                        path: "links/a.rbsync".into(),
                    },
                    targets: vec![LinkTargetRef {
                        service: "StarterGui".into(),
                        path: vec!["StarterGui".into(), "CountryService".into()],
                        ords: Vec::new(),
                    }],
                }],
                broken: Vec::new(),
            },
        )
        .unwrap();

        let error = link_add(LinkAddArgs {
            project_root: dir.clone(),
            manifest: PathBuf::from("renium-link.json"),
            id: Some("country-b".into()),
            source_type: "local".into(),
            source: Some("links/b.rbsync".into()),
            source_ref: None,
            source_subpath: None,
            service: "StarterGui".into(),
            path_segments_json: r#"["StarterGui","CountryService"]"#.into(),
            path_ordinals_json: "[]".into(),
            writable: false,
            pretty: false,
        })
        .unwrap_err()
        .to_string();

        assert!(error.contains("already a renium-link target"));
        assert_eq!(read_link_manifest(&manifest_path).unwrap().links.len(), 1);
        fs::remove_dir_all(dir).unwrap();
    }

