    #[test]
    fn materialize_package_splices_any_instance_subtree() {
        let root = link_test_dir("pkg");
        let src_root = root.join("src");

        let mut anchored = Map::new();
        anchored.insert("Anchored".to_string(), json!(true));
        let mut source = Map::new();
        source.insert("Source".to_string(), json!("return 42"));
        let package = SettingsBytecode {
            version: SETTINGS_BINARY_VERSION,
            instances: vec![
                SettingsBytecodeInstance {
                    settings_id: "pkg:0".into(),
                    name: "Widget".into(),
                    class_name: "Folder".into(),
                    parent_index: None,
                    properties: Map::new(),
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "pkg:1".into(),
                    name: "Block".into(),
                    class_name: "Part".into(),
                    parent_index: Some(0),
                    properties: anchored,
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "pkg:2".into(),
                    name: "Mod".into(),
                    class_name: "ModuleScript".into(),
                    parent_index: Some(0),
                    properties: source,
                    attributes: Map::new(),
                },
            ],
        };
        let package_path = root.join("widget.rbsync");
        package.write_file(&package_path).unwrap();

        let mut doc = SettingsBytecode {
            version: SETTINGS_BINARY_VERSION,
            instances: vec![SettingsBytecodeInstance {
                settings_id: "editor:0".into(),
                name: "ReplicatedStorage".into(),
                class_name: "ReplicatedStorage".into(),
                parent_index: None,
                properties: Map::new(),
                attributes: Map::new(),
            }],
        };
        let (changed, ids, _removed) = materialize_package_target(
            &mut doc,
            PackageMaterialization {
                service_dir: &src_root.join("ReplicatedStorage"),
                service: "ReplicatedStorage",
                target_segments: &["Pkgs".to_string(), "Widget".to_string()],
                target_ordinals: &[],
                package_path: &package_path,
                read_only: true,
                filesystem_target: true,
                external_references: &HashSet::new(),
            },
        )
        .unwrap();

        assert!(
            doc.instances
                .iter()
                .any(|i| i.name == "Widget" && i.class_name == "Folder")
        );
        let block = doc.instances.iter().find(|i| i.name == "Block").unwrap();
        assert_eq!(block.class_name, "Part");
        assert_eq!(block.properties.get("Anchored"), Some(&json!(true)));
        let module = doc.instances.iter().find(|i| i.name == "Mod").unwrap();
        assert_eq!(module.properties.get("Source"), Some(&json!("return 42")));
        assert_eq!(ids.len(), 3);
        assert!(changed.is_empty());
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn package_target_migrates_old_source_mirrors_into_bytecode() {
        let root = link_test_dir("pkg-migrate");
        let src_root = root.join("src");
        let svc_dir = src_root.join("ServerStorage");
        fs::create_dir_all(svc_dir.join("Widget")).unwrap();
        let mirror_path = svc_dir.join("Widget").join("Mod.luau");
        fs::write(&mirror_path, "return 42").unwrap();

        let mut source = Map::new();
        source.insert("Source".to_string(), json!("return 42"));
        let package = SettingsBytecode {
            version: SETTINGS_BINARY_VERSION,
            instances: vec![
                SettingsBytecodeInstance {
                    settings_id: "pkg:0".into(),
                    name: "Widget".into(),
                    class_name: "Folder".into(),
                    parent_index: None,
                    properties: Map::new(),
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "pkg:1".into(),
                    name: "Mod".into(),
                    class_name: "ModuleScript".into(),
                    parent_index: Some(0),
                    properties: source,
                    attributes: Map::new(),
                },
            ],
        };
        let package_path = root.join("widget.rbsync");
        package.write_file(&package_path).unwrap();

        let mut doc = SettingsBytecode {
            version: SETTINGS_BINARY_VERSION,
            instances: vec![
                SettingsBytecodeInstance {
                    settings_id: "editor:0".into(),
                    name: "ServerStorage".into(),
                    class_name: "ServerStorage".into(),
                    parent_index: None,
                    properties: Map::new(),
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "editor:1".into(),
                    name: "Widget".into(),
                    class_name: "Folder".into(),
                    parent_index: Some(0),
                    properties: Map::new(),
                    attributes: Map::new(),
                },
                SettingsBytecodeInstance {
                    settings_id: "editor:2".into(),
                    name: "Mod".into(),
                    class_name: "ModuleScript".into(),
                    parent_index: Some(1),
                    properties: Map::new(),
                    attributes: Map::new(),
                },
            ],
        };

        let package_sources = package_inline_source_relative_paths(&package);
        assert!(package_target_needs_inline_source_migration(
            &doc,
            "ServerStorage",
            &svc_dir,
            &["Widget".to_string()],
            &[],
            &package_sources,
        ));

        let (removals, _ids, _removed) = materialize_package_target(
            &mut doc,
            PackageMaterialization {
                service_dir: &svc_dir,
                service: "ServerStorage",
                target_segments: &["Widget".to_string()],
                target_ordinals: &[],
                package_path: &package_path,
                read_only: true,
                filesystem_target: true,
                external_references: &HashSet::new(),
            },
        )
        .unwrap();

        assert_eq!(removals, vec![mirror_path.clone()]);
        apply_file_mutations(&BTreeMap::new(), &removals).unwrap();
        assert!(!mirror_path.exists());
        let module = doc.instances.iter().find(|i| i.name == "Mod").unwrap();
        assert_eq!(module.properties.get("Source"), Some(&json!("return 42")));
        assert!(!package_target_needs_inline_source_migration(
            &doc,
            "ServerStorage",
            &svc_dir,
            &["Widget".to_string()],
            &[],
            &package_sources,
        ));
        let _ = fs::remove_dir_all(&root);
    }

